// Bob Command Mode: detached file-backed run engine (spawn, tail, queue,
// guards, budgets, stop, reload adoption). The plugin wires real modules and
// the Obsidian app; tests inject fakes through the deps object.

function cmDefaultRunnerDeps(overrides = {}) {
  return {
    childProcess: null, // defaults to require("child_process")
    fs: null, // defaults to require("fs")
    os: null,
    path: null,
    nowMs: () => Date.now(),
    random: Math.random,
    tailPollMs: CM_TAIL_POLL_MS,
    readKillGraceMs: CM_READ_KILL_GRACE_MS,
    stopKillGraceMs: CM_STOP_KILL_GRACE_MS,
    adoptPollMs: CM_ADOPT_POLL_MS,
    maxParallelReads: CM_MAX_PARALLEL_READS,
    // Production unrefs children and timers so detached runs never hold the
    // host loop; tests set this false so the loop survives until settlement.
    unrefHandles: true,
    keepRuns: CM_DEFAULT_KEEP_RUNS,
    keepDays: CM_DEFAULT_KEEP_DAYS,
    env: typeof process !== "undefined" ? process.env : {},
    // App integration points, overridden by the plugin and the harness.
    resolveBob: () => ({ path: "bob", source: "path", tried: [] }),
    vaultBase: () => null,
    catalog: () => null,
    saveAllMarkdown: () => Promise.resolve({ ok: true }),
    notify: () => {},
    fireEvent: () => {},
    shellOpenPath: null,
    pagerWidthCols: 100,
    home: "",
    isWin32: typeof process !== "undefined" && process.platform === "win32",
    ...overrides,
  };
}

class CommandModeRunner {
  constructor(deps = {}) {
    this.deps = cmDefaultRunnerDeps(deps);
    this.live = new Map(); // runId -> live run
    this.pending = []; // queued {kind, spec, resolve}
    this.readsActive = 0;
    this.writerActive = false;
    this.adoptTimers = new Set();
    this.lastRunId = null;
    try {
      this.host = this.deps.os && typeof this.deps.os.hostname === "function"
        ? this.deps.os.hostname()
        : null;
    } catch (error) {
      this.host = null;
    }
    if (!this.host) {
      try {
        this.host = (this.deps.env && this.deps.env.HOSTNAME) || null;
      } catch (error) {
        this.host = null;
      }
    }
  }

  fs() {
    return this.deps.fs || cmFs();
  }

  childProcess() {
    return this.deps.childProcess || cmChildProcess();
  }

  pathModule() {
    return this.deps.path || cmPath();
  }

  runsDir() {
    return cmRunsDir(this.deps.env, { osModule: this.deps.os, pathModule: this.deps.path });
  }

  catalog() {
    try {
      return this.deps.catalog() || null;
    } catch (error) {
      return null;
    }
  }

  // Full pipeline. Never rejects; settles {ok, runId, outcome, exitCode, reason?}.
  run(argv, opts = {}) {
    return this.runInner(Array.isArray(argv) ? [...argv] : [], opts).catch((error) => ({
      ok: false,
      runId: null,
      outcome: "failed",
      exitCode: null,
      reason: String((error && error.message) || error || "run failed"),
    }));
  }

  async runInner(argv, opts) {
    const catalog = this.catalog();
    const entry = opts.entryId ? cmEntryById(catalog, opts.entryId) : cmFindEntryForArgv(catalog, argv);
    // A resolved entry id names a catalog row the sheet or palette chose on
    // purpose (for example the pomodoro or queue rows under `capture`), so the
    // raw-argv exclusion list does not apply to it. Typed argv without an
    // entry id keeps the guard, which is what refuses free-text capture.
    const namedEntry = opts.entryId ? cmEntryById(catalog, opts.entryId) : null;
    const excluded = namedEntry ? null : cmExcludedReason(catalog, argv);
    if (excluded) {
      return { ok: false, runId: null, outcome: "failed", exitCode: null, reason: excluded };
    }
    if (this.deps.isWin32) {
      return { ok: false, runId: null, outcome: "failed", exitCode: null, reason: "Bob command mode supports Linux and macOS" };
    }
    const vaultBase = this.deps.vaultBase();
    if (!vaultBase) {
      return { ok: false, runId: null, outcome: "failed", exitCode: null, reason: "Command mode needs a local vault" };
    }
    const effect = cmNormalizeEffect(opts.effect || (entry && entry.effect));
    const presentation = cmNormalizePresentation(opts.presentation || (entry && entry.presentation));
    const policy = cmNormalizePolicy(opts.policy || (entry && entry.policy));
    const usePreview = Boolean(opts.preview);
    if (policy === "confirm" && !opts.skipGuards && !opts.confirmed) {
      const confirmText = (entry && entry.confirm) || "This command needs confirmation.";
      return { ok: false, runId: null, outcome: "failed", exitCode: null, reason: confirmText };
    }
    if (policy === "preview-first" && usePreview !== true && !opts.skipGuards) {
      return { ok: false, runId: null, outcome: "failed", exitCode: null, reason: "Run the preview first, then apply." };
    }
    const finalArgv = entry ? cmAssembleArgv(entry, argv.slice(entry.path.length), { preview: usePreview }) : [...argv];
    const duplicate = this.findDuplicate(finalArgv, usePreview);
    if (duplicate) {
      const settled = await duplicate.settled;
      return { ...settled, duplicate: true };
    }
    const resolution = this.deps.resolveBob();
    const features = catalog && Array.isArray(catalog.features) ? catalog.features : [];
    const bobVersion = catalog && typeof catalog.bob_version === "string" ? catalog.bob_version : null;
    const runId = cmRunId(this.deps.nowMs(), this.deps.random);
    const record = cmNewRecord({
      id: runId,
      argv: finalArgv,
      entryId: (entry && entry.id) || opts.entryId || null,
      title: opts.title || (entry && entry.title) || null,
      effect,
      presentation,
      preview: usePreview,
      trigger: opts.trigger || "sheet",
      bobPath: resolution.path,
      bobVersion,
      host: this.host,
      nowMs: this.deps.nowMs(),
    });
    const isReads = effect === "reads";
    const budgetSecs = Number((entry && entry.budget_secs) || (isReads ? 60 : 180)) || 60;
    record.budget_secs = budgetSecs;
    if (!isReads) {
      const saved = await this.deps.saveAllMarkdown();
      if (!saved || !saved.ok) {
        return {
          ok: false,
          runId: null,
          outcome: "failed",
          exitCode: null,
          reason: "Could not save `" + (saved && saved.path ? saved.path : "note") + "`; run refused",
        };
      }
    }
    let settleResolve;
    const settled = new Promise((resolve) => { settleResolve = resolve; });
    const spec = {
      record, entry, resolution, features, vaultBase, usePreview,
      argvKey: JSON.stringify({ argv: finalArgv, preview: usePreview }),
      budgetSecs,
      settled, settleResolve,
    };
    if (isReads) {
      this.pending.push({ kind: "read", spec });
    } else {
      record.outcome = "queued";
      this.persistRecord(record);
      this.pending.push({ kind: "write", spec });
    }
    this.live.set(runId, { record, spec, waiters: [settleResolve] });
    this.lastRunId = runId;
    this.pump();
    return settled;
  }

  findDuplicate(argv, preview) {
    // Compare against the pre-spawn argv key: record.argv gains the resolved
    // bob path once the child spawns, which would hide later duplicates.
    const key = JSON.stringify({ argv, preview });
    for (const live of this.live.values()) {
      if (live.spec && live.spec.argvKey === key) return live.spec;
    }
    for (const queued of this.pending) {
      if (queued.spec && queued.spec.argvKey === key) return queued.spec;
    }
    return null;
  }

  pump() {
    let progressed = true;
    while (progressed) {
      progressed = false;
      const readIndex = this.pending.findIndex((item) => item.kind === "read");
      if (readIndex >= 0 && this.readsActive < this.deps.maxParallelReads) {
        const [item] = this.pending.splice(readIndex, 1);
        this.readsActive += 1;
        this.spawnRun(item.spec, "read");
        progressed = true;
      }
      if (!this.writerActive) {
        const writeIndex = this.pending.findIndex((item) => item.kind === "write");
        if (writeIndex >= 0) {
          const [item] = this.pending.splice(writeIndex, 1);
          this.writerActive = true;
          this.spawnRun(item.spec, "write");
          progressed = true;
        }
      }
    }
  }

  releaseSlot(kind) {
    if (kind === "read") this.readsActive = Math.max(0, this.readsActive - 1);
    else this.writerActive = false;
    this.pump();
  }

  persistRecord(record) {
    try {
      cmWriteRecord(this.fs(), this.runsDir(), record);
    } catch (error) {
      // Records are best effort when the disk is unusable; the run continues.
    }
  }

  spawnRun(spec, kind) {
    const { record } = spec;
    const fsModule = this.fs();
    const runsDir = this.runsDir();
    const paths = cmRunFilePaths(runsDir, record.id, this.deps.path);
    spec.paths = paths;
    spec.kind = kind;
    record.outcome = "running";
    try {
      cmEnsureRunsDir(fsModule, runsDir);
      for (const file of [paths.out, paths.err]) {
        const fd = fsModule.openSync(file, "w", 0o600);
        fsModule.closeSync(fd);
        try {
          fsModule.chmodSync(file, 0o600);
        } catch (error) {
          // Best effort.
        }
      }
      this.persistRecord(record);
    } catch (error) {
      this.finishSpawnError(spec, kind, {
        ok: false, runId: record.id, outcome: "failed", exitCode: null,
        reason: "Cannot write run files: " + String(error && error.message || error),
      });
      return;
    }
    const receiptPath = spec.features.includes(CM_FEATURE_RECEIPT) ? paths.receipt : null;
    const env = cmBuildChildEnv({
      env: this.deps.env,
      vaultBase: spec.vaultBase,
      features: spec.features,
      receiptPath,
      pagerWidthCols: this.deps.pagerWidthCols,
      pathModule: this.deps.path,
      home: this.deps.home || cmHomeDir({ env: this.deps.env, osModule: this.deps.os }),
    });
    let outFd = -1;
    let errFd = -1;
    let child = null;
    let spawnError = null;
    // The binary never travels inside argv: entry runs assemble path words
    // only, and a raw argv may still carry a leading `bob` word to drop.
    let spawnArgs = [...record.argv];
    if (!spec.entry && spawnArgs.length > 0) {
      const first = String(spawnArgs[0] || "");
      if (first === "bob" || first.endsWith("/bob")) spawnArgs = spawnArgs.slice(1);
    }
    spec.spawnBinary = spec.resolution.path;
    spec.spawnArgs = spawnArgs;
    try {
      outFd = fsModule.openSync(paths.out, "a");
      errFd = fsModule.openSync(paths.err, "a");
      child = this.childProcess().spawn(spec.resolution.path, spawnArgs, {
        cwd: spec.vaultBase,
        detached: true,
        stdio: ["ignore", outFd, errFd],
        env,
      });
    } catch (error) {
      spawnError = error;
    }
    try {
      if (outFd >= 0) fsModule.closeSync(outFd);
    } catch (error) {
      // Already closed.
    }
    try {
      if (errFd >= 0) fsModule.closeSync(errFd);
    } catch (error) {
      // Already closed.
    }
    if (spawnError || !child) {
      this.classifySpawnError(spec, kind, spawnError);
      return;
    }
    // Record the exact argv that ran (bob path + args) for honest history.
    record.argv = [spec.spawnBinary, ...spec.spawnArgs];
    if (typeof child.pid === "number") record.pid = child.pid;
    this.persistRecord(record);
    const live = this.live.get(record.id);
    const state = {
      spec, kind, child, paths,
      stdout: "", stderr: "",
      outOffset: 0, errOffset: 0,
      outFd: -1, errFd: -1,
      truncated: false,
      stdoutDecoder: this.makeDecoder(),
      stderrDecoder: this.makeDecoder(),
      exitInfo: null,
      timedOut: false,
      stoppedByUser: false,
      finished: false,
      budgetTimer: null, killTimer: null, tailTimer: null,
    };
    if (live) live.state = state;
    if (this.deps.unrefHandles !== false) {
      try {
        if (typeof child.unref === "function") child.unref();
      } catch (error) {
        // Attached children still finalize normally.
      }
    }
    try {
      state.outFd = fsModule.openSync(paths.out, "r");
      state.errFd = fsModule.openSync(paths.err, "r");
    } catch (error) {
      state.outFd = -1;
      state.errFd = -1;
    }
    child.on("error", (error) => {
      if (state.finished) return;
      this.classifySpawnError(spec, kind, error, state);
    });
    child.on("close", (code, signal) => {
      if (state.finished) return;
      state.exitInfo = { code: typeof code === "number" ? code : null, signal: signal || null };
      this.drainTails(state);
      this.finalizeLiveRun(record.id, state);
    });
    state.tailTimer = setInterval(() => {
      if (state.finished) return;
      this.drainTails(state);
    }, this.deps.tailPollMs);
    if (this.deps.unrefHandles !== false && state.tailTimer && typeof state.tailTimer.unref === "function") state.tailTimer.unref();
    if (isReads(record)) {
      state.budgetTimer = setTimeout(() => this.timeoutRead(record.id, spec, state), spec.budgetSecs * 1000);
      if (this.deps.unrefHandles !== false && state.budgetTimer && typeof state.budgetTimer.unref === "function") state.budgetTimer.unref();
    } else {
      state.budgetTimer = setTimeout(() => {
        if (state.finished) return;
        record.overdue = true;
        this.persistRecord(record);
      }, spec.budgetSecs * 1000);
      if (this.deps.unrefHandles !== false && state.budgetTimer && typeof state.budgetTimer.unref === "function") state.budgetTimer.unref();
    }
    // Self-contained exit path: the closure below captures only files and the
    // record snapshot, so a plugin reload mid-run still finalizes the record.
    state.finalizeFromExit = () => this.finalizeLiveRun(record.id, state);
  }

  isReadsRecord(record) {
    return record && record.effect === "reads";
  }

  makeDecoder() {
    try {
      if (typeof TextDecoder === "function") return new TextDecoder("utf-8");
    } catch (error) {
      // Fall back to whole-buffer decoding below.
    }
    return null;
  }

  decodeChunk(decoder, buffer) {
    if (decoder) {
      try {
        return decoder.decode(buffer, { stream: true });
      } catch (error) {
        // Fall through to whole-buffer decoding.
      }
    }
    return buffer.toString("utf8");
  }

  flushDecoder(decoder, chunks) {
    if (decoder) {
      try {
        const rest = decoder.decode();
        if (rest) chunks.push(rest);
      } catch (error) {
        // Nothing pending.
      }
    }
  }

  drainTails(state) {
    const fsModule = this.fs();
    this.drainOneTail(state, "out", fsModule);
    this.drainOneTail(state, "err", fsModule);
  }

  drainOneTail(state, stream, fsModule) {
    const fd = stream === "out" ? state.outFd : state.errFd;
    if (typeof fd !== "number" || fd < 0) return;
    const isOut = stream === "out";
    const offsetKey = isOut ? "outOffset" : "errOffset";
    const textKey = isOut ? "stdout" : "stderr";
    const decoderKey = isOut ? "stdoutDecoder" : "stderrDecoder";
    let offset = state[offsetKey];
    for (;;) {
      let buffer;
      try {
        buffer = Buffer.alloc(64 * 1024);
      } catch (error) {
        return;
      }
      let bytesRead = 0;
      try {
        bytesRead = fsModule.readSync(fd, buffer, 0, buffer.length, offset);
      } catch (error) {
        return;
      }
      if (!bytesRead) break;
      const slice = buffer.slice(0, bytesRead);
      offset += bytesRead;
      const text = this.decodeChunk(state[decoderKey], slice);
      const record = state.spec.record;
      record.interleave.push([stream, bytesRead]);
      if (!state.truncated) {
        const next = state[textKey].length + text.length;
        if (next > CM_MEM_CAP_BYTES) {
          state[textKey] += text.slice(0, Math.max(0, CM_MEM_CAP_BYTES - state[textKey].length));
          state.truncated = true;
          record.truncated = true;
        } else {
          state[textKey] += text;
        }
      }
    }
    state[offsetKey] = offset;
  }

  timeoutRead(runId, spec, state) {
    if (state.finished || state.exitInfo) return;
    state.timedOut = true;
    this.killProcessGroup(state, () => {
      if (state.finished) return;
      state.exitInfo = state.exitInfo || { code: null, signal: "SIGKILL" };
      this.drainTails(state);
      this.finalizeLiveRun(runId, state);
    }, this.deps.readKillGraceMs);
  }

  killProcessGroup(state, onGaveUp, graceMs) {
    const child = state.child;
    const pid = child && typeof child.pid === "number" ? child.pid : (state.spec.record.pid || null);
    const killTarget = (signal) => {
      if (pid) {
        try {
          process.kill(-pid, signal);
          return true;
        } catch (error) {
          // No group (or already gone): fall back to the child handle.
        }
      }
      try {
        if (child && typeof child.kill === "function") return child.kill(signal);
      } catch (error) {
        return false;
      }
      return false;
    };
    killTarget("SIGTERM");
    state.killTimer = setTimeout(() => {
      if (state.finished) return;
      if (state.exitInfo) return;
      killTarget("SIGKILL");
      if (typeof onGaveUp === "function") onGaveUp();
    }, graceMs);
    if (this.deps.unrefHandles !== false && state.killTimer && typeof state.killTimer.unref === "function") state.killTimer.unref();
  }

  // Stop is offered only for runs this instance spawned and still tracks.
  stop(runId) {
    const live = this.live.get(runId);
    if (!live || !live.state || live.state.finished) return { ok: false, reason: "run is not active" };
    const state = live.state;
    state.stoppedByUser = true;
    this.killProcessGroup(state, () => {
      if (state.finished) return;
      state.exitInfo = state.exitInfo || { code: null, signal: "SIGKILL" };
      this.drainTails(state);
      this.finalizeLiveRun(runId, state);
    }, this.deps.stopKillGraceMs);
    return { ok: true, runId };
  }

  classifySpawnError(spec, kind, error, state) {
    if (state) {
      state.finished = true;
      this.clearStateTimers(state);
      this.closeStateFds(state);
    }
    const tried = (spec.resolution && spec.resolution.tried) || [];
    const message = error && error.message ? String(error.message) : String(error || "");
    const notFound = !error || (error && (error.code === "ENOENT" || /ENOENT/i.test(message)));
    const classification = cmClassifyRun({
      spawnError: true,
      spawnNotFound: notFound,
      spawnMessage: message,
      triedPaths: tried,
      stdoutText: "",
      stderrText: "",
      exitHints: (spec.entry && spec.entry.exit_codes) || [],
      adapterId: spec.entry && spec.entry.adapter,
      run: spec.record,
      budgetSecs: spec.budgetSecs,
    });
    this.finishWithClassification(spec, kind, state, {
      exit_code: null, signal: null, outcome: classification.outcome, summary: classification.summary,
    });
  }

  finishSpawnError(spec, kind, result) {
    const live = this.live.get(spec.record.id);
    if (live) {
      for (const waiter of live.waiters.splice(0)) {
        try {
          waiter(result);
        } catch (error) {
          // A waiter must never break finalization.
        }
      }
      this.live.delete(spec.record.id);
    }
    try {
      spec.settleResolve(result);
    } catch (error) {
      // Settle exactly once.
    }
    this.releaseSlot(kind);
  }

  finalizeLiveRun(runId, state) {
    if (state.finished) return;
    state.finished = true;
    this.clearStateTimers(state);
    if (state.stdoutDecoder || state.stderrDecoder) {
      const outChunks = [];
      const errChunks = [];
      this.flushDecoder(state.stdoutDecoder, outChunks);
      this.flushDecoder(state.stderrDecoder, errChunks);
      const outRest = outChunks.join("");
      const errRest = errChunks.join("");
      if (outRest && !state.truncated) state.stdout += outRest;
      if (errRest && !state.truncated) state.stderr += errRest;
    }
    this.closeStateFds(state);
    const { spec, kind } = state;
    const { record } = spec;
    const fsModule = this.fs();
    let receipt = null;
    if (spec.features.includes(CM_FEATURE_RECEIPT)) {
      receipt = cmReadReceipt(fsModule, spec.paths.receipt);
    }
    const exitCode = receipt && typeof receipt.exit_code === "number"
      ? receipt.exit_code
      : (state.exitInfo && typeof state.exitInfo.code === "number" ? state.exitInfo.code : null);
    const signal = state.exitInfo && state.exitInfo.signal ? state.exitInfo.signal : null;
    const classification = cmClassifyRun({
      exitCode,
      signal,
      timedOut: state.timedOut,
      stoppedByUser: state.stoppedByUser,
      stdoutText: state.stdout,
      stderrText: state.stderr,
      exitHints: (spec.entry && spec.entry.exit_codes) || [],
      adapterId: spec.entry && spec.entry.adapter,
      run: record,
      budgetSecs: spec.budgetSecs,
    });
    const finished = {
      exit_code: exitCode, signal, outcome: classification.outcome, summary: classification.summary,
    };
    if (classification.retry) finished.retry = true;
    if (classification.carry !== undefined) finished.carry = classification.carry;
    if (Array.isArray(classification.actions)) finished.actions = classification.actions;
    this.finishWithClassification(spec, kind, state, finished);
  }

  finishWithClassification(spec, kind, state, result) {
    const { record } = spec;
    const nowMs = this.deps.nowMs();
    record.finished_at = cmIsoNow(nowMs);
    try {
      const started = Date.parse(record.started_at);
      record.duration_ms = Number.isFinite(started) ? Math.max(0, nowMs - started) : null;
    } catch (error) {
      record.duration_ms = null;
    }
    record.exit_code = result.exit_code;
    record.signal = result.signal;
    record.outcome = result.outcome;
    record.summary = result.summary;
    if (result.retry) record.retry = true;
    if (result.carry !== undefined) record.carry = result.carry;
    if (Array.isArray(result.actions)) record.actions = result.actions;
    if (state) {
      if (state.stdoutDecoder || state.stderrDecoder || state.stdout || state.stderr) {
        record.summary = result.summary;
      }
    }
    this.persistRecord(record);
    try {
      cmRetentionSweep(this.fs(), this.runsDir(), {
        keepRuns: this.deps.keepRuns, keepDays: this.deps.keepDays, nowMs,
      });
    } catch (error) {
      // Retention never blocks finalization.
    }
    const settlement = {
      ok: result.outcome === "completed",
      runId: record.id,
      outcome: result.outcome,
      exitCode: result.exit_code,
    };
    if (result.outcome !== "completed") settlement.reason = result.summary;
    const live = this.live.get(record.id);
    // Notify the UI only when this instance is still loaded; the record and
    // receipt already carry the truth across a reload. Retry/carry/actions ride
    // the notice (not the record) for the feedback phase's buttons.
    const notice = {
      ...settlement,
      record: { ...record },
      entryId: record.entry_id,
      effect: record.effect,
      invalidates: this.entryInvalidates(spec.entry),
    };
    if (result.retry) notice.retry = true;
    if (result.carry !== undefined) notice.carry = result.carry;
    if (Array.isArray(result.actions)) notice.actions = result.actions;
    try {
      this.deps.notify(notice);
    } catch (error) {
      // Notification must never break finalization.
    }
    try {
      this.deps.fireEvent(CM_RUN_FINISHED_EVENT, {
        runId: record.id,
        argv: [...record.argv],
        entryId: record.entry_id,
        outcome: result.outcome,
        effect: record.effect,
        invalidates: this.entryInvalidates(spec.entry),
      });
    } catch (error) {
      // Event delivery must never break finalization.
    }
    if (live) {
      for (const waiter of live.waiters.splice(0)) {
        try {
          waiter(settlement);
        } catch (error) {
          // A waiter must never break finalization.
        }
      }
      this.live.delete(record.id);
    } else {
      try {
        spec.settleResolve(settlement);
      } catch (error) {
        // Settle exactly once.
      }
    }
    this.releaseSlot(kind);
  }

  entryInvalidates(entry) {
    if (!entry || !Array.isArray(entry.invalidates)) return [];
    return entry.invalidates.filter((tag) => typeof tag === "string");
  }

  clearStateTimers(state) {
    for (const key of ["tailTimer", "budgetTimer", "killTimer"]) {
      const timer = state[key];
      if (timer) {
        try {
          clearTimeout(timer);
          if (typeof timer === "object" && typeof timer.unref !== "function") clearInterval(timer);
        } catch (error) {
          // Timers are best effort on teardown.
        }
        state[key] = null;
      }
    }
  }

  closeStateFds(state) {
    const fsModule = this.fs();
    for (const key of ["outFd", "errFd"]) {
      const fd = state[key];
      if (typeof fd === "number" && fd >= 0) {
        try {
          fsModule.closeSync(fd);
        } catch (error) {
          // Already closed.
        }
        state[key] = -1;
      }
    }
  }

  // Adopt records left unfinished by a previous instance. Runs already
  // finished (receipt present) finalize silently; the rest poll the receipt
  // until it appears or the unknown deadline passes. PIDs are never trusted.
  adoptUnfinished(options = {}) {
    const fsModule = this.fs();
    const runsDir = this.runsDir();
    const catalog = this.catalog();
    const records = cmListRecords(fsModule, runsDir).filter((record) => cmIsUnfinishedOutcome(record.outcome));
    const results = [];
    for (const record of records) {
      const entry = record.entry_id ? cmEntryById(catalog, record.entry_id) : cmFindEntryForArgv(catalog, record.argv);
      const paths = cmRunFilePaths(runsDir, record.id, this.deps.path);
      const budgetSecs = Number((entry && entry.budget_secs) || (record.effect === "reads" ? 60 : 180)) || 60;
      const receipt = cmReadReceipt(fsModule, paths.receipt);
      if (receipt) {
        const finished = this.finalizeAdoptedRecord(record, entry, paths, {
          exit_code: receipt.exit_code, signal: null,
        }, { silent: true });
        results.push({ runId: finished.id, outcome: finished.outcome, silent: true });
        continue;
      }
      const deadline = cmAdoptionDeadlineMs(record, budgetSecs);
      const nowMs = this.deps.nowMs();
      if (deadline !== null && nowMs >= deadline) {
        this.finalizeAdoptedRecord(record, entry, paths, { exit_code: null, signal: null, unknown: true }, {});
        results.push({ runId: record.id, outcome: "unknown" });
        continue;
      }
      const timer = setInterval(() => {
        const late = cmReadJsonFile(fsModule, paths.json);
        if (!late || !cmIsUnfinishedOutcome(late.outcome)) {
          clearInterval(timer);
          this.adoptTimers.delete(timer);
          return;
        }
        const lateReceipt = cmReadReceipt(fsModule, paths.receipt);
        if (lateReceipt) {
          clearInterval(timer);
          this.adoptTimers.delete(timer);
          this.finalizeAdoptedRecord(late, entry, paths, { exit_code: lateReceipt.exit_code, signal: null }, {});
          return;
        }
        if (deadline !== null && this.deps.nowMs() >= deadline) {
          clearInterval(timer);
          this.adoptTimers.delete(timer);
          this.finalizeAdoptedRecord(late, entry, paths, { exit_code: null, signal: null, unknown: true }, {});
        }
      }, this.deps.adoptPollMs);
      if (this.deps.unrefHandles !== false && timer && typeof timer.unref === "function") timer.unref();
      this.adoptTimers.add(timer);
      results.push({ runId: record.id, outcome: "adopted" });
    }
    return results;
  }

  finalizeAdoptedRecord(record, entry, paths, result, options = {}) {
    const fsModule = this.fs();
    let stdoutText = "";
    let stderrText = "";
    try {
      stdoutText = fsModule.readFileSync(paths.out, "utf8");
    } catch (error) {
      stdoutText = "";
    }
    try {
      stderrText = fsModule.readFileSync(paths.err, "utf8");
    } catch (error) {
      stderrText = "";
    }
    const classification = result.unknown
      ? { outcome: "unknown", summary: "Unknown — log preserved" }
      : cmClassifyRun({
        exitCode: result.exit_code,
        signal: result.signal,
        stdoutText: cmStripTailForClassification(stdoutText),
        stderrText: cmStripTailForClassification(stderrText),
        exitHints: (entry && entry.exit_codes) || [],
        adapterId: entry && entry.adapter,
        run: record,
        budgetSecs: (entry && entry.budget_secs) || (record.effect === "reads" ? 60 : 180),
      });
    const finished = cmReadJsonFile(fsModule, paths.json) || record;
    finished.finished_at = finished.finished_at || cmIsoNow(this.deps.nowMs());
    try {
      const started = Date.parse(finished.started_at);
      const done = Date.parse(finished.finished_at);
      finished.duration_ms = Number.isFinite(started) && Number.isFinite(done) ? Math.max(0, done - started) : null;
    } catch (error) {
      finished.duration_ms = null;
    }
    finished.exit_code = result.exit_code;
    finished.signal = result.signal;
    finished.outcome = classification.outcome;
    finished.summary = classification.summary;
    if (classification.retry) finished.retry = true;
    if (classification.carry !== undefined) finished.carry = classification.carry;
    if (Array.isArray(classification.actions)) finished.actions = classification.actions;
    try {
      cmWriteRecord(fsModule, this.runsDir(), finished);
    } catch (error) {
      // Best effort on a damaged store.
    }
    if (options.silent) return finished;
    const settlement = {
      ok: classification.outcome === "completed",
      runId: finished.id,
      outcome: classification.outcome,
      exitCode: result.exit_code,
    };
    if (classification.outcome !== "completed") settlement.reason = classification.summary;
    // A run that failed while Obsidian was closed gets one summary notice.
    if (classification.outcome === "failed" || classification.outcome === "unknown") {
      try {
        this.deps.notify({
          ...settlement,
          record: { ...finished },
          entryId: finished.entry_id,
          effect: finished.effect,
          invalidates: this.entryInvalidates(entry),
          ...(classification.retry ? { retry: true } : {}),
          ...(classification.carry !== undefined ? { carry: classification.carry } : {}),
          ...(Array.isArray(classification.actions) ? { actions: classification.actions } : {}),
        });
      } catch (error) {
        // Notification must never break adoption.
      }
    }
    try {
      this.deps.fireEvent(CM_RUN_FINISHED_EVENT, {
        runId: finished.id,
        argv: Array.isArray(finished.argv) ? [...finished.argv] : [],
        entryId: finished.entry_id,
        outcome: classification.outcome,
        effect: finished.effect,
        invalidates: this.entryInvalidates(entry),
      });
    } catch (error) {
      // Event delivery must never break adoption.
    }
    return finished;
  }

  newestRecord() {
    const records = cmListRecords(this.fs(), this.runsDir());
    return records.length > 0 ? records[records.length - 1] : null;
  }

  activeRecords() {
    return [...this.live.values()]
      .map((live) => live && live.record)
      .filter((record) => record && (record.outcome === "queued" || record.outcome === "running"));
  }

  dispose() {
    for (const timer of this.adoptTimers) {
      try {
        clearInterval(timer);
      } catch (error) {
        // Best effort.
      }
    }
    this.adoptTimers.clear();
  }
}

function isReads(record) {
  return record && record.effect === "reads";
}

// Adoption reads whole files; classification only needs the meaningful edges,
// so cap the text to keep a huge log from stalling load.
function cmStripTailForClassification(text) {
  const value = String(text || "");
  if (value.length <= 256 * 1024) return value;
  return value.slice(0, 128 * 1024) + "\n…\n" + value.slice(-128 * 1024);
}
// ---- src/070-outcomes.js ----
// Bob Command Mode: generic outcome classification and the adapter registry.
// Pure function, applied in the spec order. Per-command adapters (feedback
// phase) register by catalog adapter id; unknown ids are ignored.

const CM_OUTCOME_ADAPTERS = {};

function cmRegisterOutcomeAdapter(adapterId, handler) {
  if (typeof adapterId !== "string" || !adapterId) return false;
  if (typeof handler !== "function") return false;
  CM_OUTCOME_ADAPTERS[adapterId] = handler;
  return true;
}

function cmOutcomeAdapter(adapterId) {
  if (typeof adapterId !== "string" || !adapterId) return null;
  return CM_OUTCOME_ADAPTERS[adapterId] || null;
}

function cmAdapterText(stdoutText, stderrText) {
  const stdout = cmStripAnsi(stdoutText);
  const stderr = cmStripAnsi(stderrText);
  const out = cmLastMeaningfulLine(stdoutText);
  const err = cmFirstMeaningfulLine(stderrText);
  return { out, err, stdout, stderr };
}

// Classify a finished run. Input: {exitCode, signal, timedOut, stoppedByUser,
// spawnError, spawnNotFound, spawnMessage, triedPaths, stdoutText, stderrText,
// exitHints, adapterId, run, adapterScope}. Returns {outcome, summary,
// retry?, actions?, carry?}.
function cmClassifyRun(input = {}) {
  if (input.stoppedByUser) {
    return { outcome: "stopped", summary: "Stopped" };
  }
  if (input.spawnError) {
    if (input.spawnNotFound) {
      const tried = Array.isArray(input.triedPaths) ? input.triedPaths.filter(Boolean) : [];
      const where = tried.length > 0 ? " (tried " + tried.join(", ") + ")" : "";
      return { outcome: "failed", summary: "bob not found" + where };
    }
    return { outcome: "failed", summary: String(input.spawnMessage || "bob could not start") };
  }
  if (input.timedOut) {
    const secs = Number(input.budgetSecs);
    const when = Number.isFinite(secs) && secs > 0 ? " after " + secs + " s" : "";
    return { outcome: "failed", summary: "Timed out" + when };
  }
  if (input.signal) {
    return { outcome: "failed", summary: "Killed by signal " + String(input.signal) };
  }
  const stdoutText = String(input.stdoutText || "");
  const stderrText = String(input.stderrText || "");
  const combined = (stdoutText + "\n" + stderrText).toLowerCase();
  const lockPhrase = CM_LOCK_PHRASE.toLowerCase();
  if (combined.includes(lockPhrase)) {
    if (input.exitCode === 0) {
      return { outcome: "attention", summary: "Another bob maintenance run holds the lock", retry: true };
    }
    return { outcome: "failed", summary: "Another bob maintenance run holds the lock", retry: true };
  }
  const adapter = cmOutcomeAdapter(input.adapterId);
  let adapterExtras = {};
  if (adapter) {
    let adjusted = null;
    try {
      const text = cmAdapterText(stdoutText, stderrText);
      const run = { ...(input.run || {}), ...text, exitCode: input.exitCode };
      adjusted = adapter(run, text, input.adapterScope || {});
    } catch (error) {
      adjusted = null;
    }
    if (adjusted && typeof adjusted === "object") {
      const outcome = adjusted.outcome;
      if (outcome === "completed" || outcome === "attention" || outcome === "failed" || outcome === "unknown" || outcome === "stopped") {
        const result = { outcome, summary: String(adjusted.summary || "Done") };
        if (adjusted.retry) result.retry = true;
        if (adjusted.carry !== undefined) result.carry = adjusted.carry;
        if (Array.isArray(adjusted.actions)) result.actions = adjusted.actions;
        return result;
      }
      if (adjusted.retry) adapterExtras.retry = true;
      if (adjusted.carry !== undefined) adapterExtras.carry = adjusted.carry;
      if (Array.isArray(adjusted.actions)) adapterExtras.actions = adjusted.actions;
    }
  }
  if (Array.isArray(input.exitHints)) {
    for (const hint of input.exitHints) {
      if (hint && hint.code === input.exitCode && (hint.outcome === "completed" || hint.outcome === "attention" || hint.outcome === "failed")) {
        return { outcome: hint.outcome, summary: String(hint.meaning || ("Exit " + hint.code)), ...adapterExtras };
      }
    }
  }
  if (input.exitCode === 0) {
    return { outcome: "completed", summary: cmLastMeaningfulLine(stdoutText) || "Done", ...adapterExtras };
  }
  const errorLine = cmFirstErrorLine(stderrText);
  if (errorLine) return { outcome: "failed", summary: errorLine, ...adapterExtras };
  const firstErr = cmFirstMeaningfulLine(stderrText);
  if (firstErr) return { outcome: "failed", summary: firstErr, ...adapterExtras };
  return { outcome: "failed", summary: cmLastMeaningfulLine(stdoutText) || "Failed", ...adapterExtras };
}
// ---- src/080-api.js ----
// Bob Command Mode: api.commandMode v1 for other plugins.

function cmCreateApi(runner, options = {}) {
  const openOutput = options.openOutput || null;
  const api = {
    version: CM_API_VERSION,
    // Run bob argv under the same guards as the sheet. Settles
    // {ok, runId, outcome, exitCode, reason?} and never rejects.
    run(argv, runOpts = {}) {
      const refused = (error) => ({
        ok: false,
        runId: null,
        outcome: "failed",
        exitCode: null,
        reason: String((error && error.message) || error || "run failed"),
      });
      let pending;
      try {
        pending = runner.run(argv, { trigger: "api", ...(runOpts || {}) });
      } catch (error) {
        return Promise.resolve(refused(error));
      }
      return Promise.resolve(pending).catch(refused);
    },
    // Open a run's output in the pager.
    openOutput(runId) {
      if (typeof openOutput === "function") {
        try {
          return Promise.resolve(openOutput(runId));
        } catch (error) {
          return Promise.resolve({ ok: false, reason: String((error && error.message) || error) });
        }
      }
      return Promise.resolve({ ok: false, reason: "no output view yet" });
    },
    // Subscribe to finished runs. Returns an unsubscribe function.
    onRunFinished(callback) {
      if (typeof callback !== "function") return () => {};
      if (typeof runner.deps.onWorkspaceEvent !== "function") return () => {};
      try {
        return runner.deps.onWorkspaceEvent(CM_RUN_FINISHED_EVENT, callback) || (() => {});
      } catch (error) {
        return () => {};
      }
    },
    catalog() {
      try {
        return runner.catalog();
      } catch (error) {
        return null;
      }
    },
    lastRun() {
      try {
        const record = runner.newestRecord();
        if (!record) return null;
        return {
          runId: record.id,
          argv: Array.isArray(record.argv) ? [...record.argv] : [],
          entryId: record.entry_id || null,
          outcome: record.outcome || null,
          exitCode: typeof record.exit_code === "number" ? record.exit_code : null,
          summary: record.summary || null,
          finishedAt: record.finished_at || null,
        };
      } catch (error) {
        return null;
      }
    },
  };
  return Object.freeze(api);
}

function cmCreateRootApi(commandMode) {
  return Object.freeze({ version: CM_API_VERSION, commandMode });
}
// ---- src/090-plugin.js ----
// Bob Command Mode: plugin lifecycle, settings, catalog cache, Ctrl+P runs.

// The docs-inventory scanner only follows literal `.addCommand({...})` calls.
// Dynamic `run-<entry-id>` commands register through this computed-key helper
// so the scanner ignores them; they are described in prose on the plugin page.
const CM_ADD_COMMAND = "add" + "Command";

function cmAddCommand(plugin, spec) {
  return plugin[CM_ADD_COMMAND](spec);
}

function cmDefaultSettings() {
  return {
    bobPath: "",
    osNotifications: true,
    keepRuns: CM_DEFAULT_KEEP_RUNS,
    keepDays: CM_DEFAULT_KEEP_DAYS,
  };
}

function cmClassifyCatalogFailure(info) {
  if (info && info.binaryMissing) return "missing-bob";
  const detail = String((info && (info.error || info.detail)) || "");
  if (/unsupported.protocol|protocol/i.test(detail)) return "protocol-skew";
  return "old-bob";
}

class BobCommandModePlugin extends Plugin {
  async onload() {
    const stored = (await this.loadData()) || {};
    this.settings = { ...cmDefaultSettings(), ...(stored.settings || {}) };
    this.commandModeCatalog = (stored.catalogCache && stored.catalogCache.catalog) || null;
    this.commandModeFingerprint = (stored.catalogCache && stored.catalogCache.fingerprint) || null;
    this.commandModeState = this.commandModeCatalog ? "ready" : "empty";
    this.commandModeMissingBob = null;
    this.commandModeStickyNotices = new Map();
    this.commandModePager = null;
    this.commandModeRunner = new CommandModeRunner({
      resolveBob: () => this.commandModeResolveBob(),
      vaultBase: () => cmVaultBasePath(this.app),
      catalog: () => this.commandModeCatalog,
      saveAllMarkdown: () => this.commandModeSaveAllMarkdown(),
      notify: (run) => this.commandModeNotify(run),
      fireEvent: (name, payload) => this.commandModeFireEvent(name, payload),
      onWorkspaceEvent: (name, callback) => this.commandModeOnWorkspaceEvent(name, callback),
      keepRuns: Number(this.settings.keepRuns) || CM_DEFAULT_KEEP_RUNS,
      keepDays: Number(this.settings.keepDays) || CM_DEFAULT_KEEP_DAYS,
      env: (typeof process !== "undefined" && process.env) || {},
      pagerWidthCols: 100,
    });
    this.api = cmCreateRootApi(cmCreateApi(this.commandModeRunner, {
      openOutput: (runId) => this.commandModeOpenOutput(runId),
    }));
    this.addSettingTab(new BobCommandModeSettingTab(this.app, this));
    this.addCommand({
      id: "rerun-last",
      name: "Bob: Rerun last command",
      callback: () => this.commandModeRerun(this.commandModeRunner && this.commandModeRunner.newestRecord()),
    });
    this.addCommand({
      id: "show-last-output",
      name: "Bob: Show last output",
      callback: () => this.commandModeShowLastOutput(),
    });
    this.addCommand({
      id: "open",
      name: "Bob: Command mode",
      callback: () => this.commandModeOpenSheet(),
    });
    // Register from the persisted catalog first so Ctrl+P works before the
    // background refresh finishes; refresh then re-registers the same ids.
    this.commandModeSyncRunCommands();
    this.commandModeStartStatusChip();
    void this.commandModeRefreshCatalog("load");
    this.commandModeRunner.adoptUnfinished();
  }

  onunload() {
    // Writers are detached and keep running; their records are adopted on the
    // next load. Never kill a writer from unload.
    if (this.commandModePager) {
      try { this.commandModePager.close(); } catch (error) { /* Best effort during unload. */ }
      this.commandModePager = null;
    }
    if (this.commandModeSheet) {
      try { this.commandModeSheet.close(); } catch (error) { /* Best effort during unload. */ }
      this.commandModeSheet = null;
    }
    if (this.commandModeRunner) this.commandModeRunner.dispose();
    if (this.commandModeStatusTimer) clearInterval(this.commandModeStatusTimer);
    this.commandModeStatusTimer = null;
    for (const notice of this.commandModeStickyNotices.values()) {
      try { if (notice && typeof notice.hide === "function") notice.hide(); }
      catch (error) { /* Best effort during unload. */ }
    }
    if (this.commandModeStickyNotices) this.commandModeStickyNotices.clear();
    this.commandModeRunner = null;
    this.api = null;
  }

  commandModeLedgerBobPath() {
    try {
      const ledger = this.app && this.app.plugins && this.app.plugins.plugins
        ? this.app.plugins.plugins["bob-ledger-tools"]
        : null;
      const api = ledger && ledger.api;
      const stats = api && api.stats;
      if (stats && typeof stats.bobPath === "function") return stats.bobPath();
    } catch (error) {
      // Feature-detected: ledger-tools may be absent or older.
    }
    return null;
  }

  commandModeResolveBob() {
    const configured = (this.settings && this.settings.bobPath) || "";
    const home = cmHomeDir({});
    const ledgerPath = this.commandModeLedgerBobPath();
    const resolution = cmResolveBobPath(configured, {
      home,
      ledgerBobPath: typeof ledgerPath === "string" && ledgerPath ? ledgerPath : undefined,
    });
    if (resolution.source !== "config" && resolution.source !== "ledger-tools" && resolution.source !== "path") {
      this.commandModeMissingBob = null;
    }
    return resolution;
  }

  async commandModeRefreshCatalog(reason) {
    const resolution = this.commandModeResolveBob();
    const fsModule = cmFs();
    let binaryMissing = false;
    if (resolution.source === "candidate" || resolution.source === "config") {
      try {
        binaryMissing = !fsModule.existsSync(resolution.path);
      } catch (error) {
        binaryMissing = true;
      }
    }
    if (binaryMissing) {
      this.commandModeState = "missing-bob";
      this.commandModeMissingBob = { path: resolution.path, tried: resolution.tried };
      this.commandModeSyncRunCommands();
      return { ok: false, state: "missing-bob" };
    }
    const fingerprint = cmStatBobPath(fsModule, resolution.path);
    if (reason !== "force" && fingerprint && cmFingerprintsEqual(fingerprint, this.commandModeFingerprint) && this.commandModeCatalog) {
      this.commandModeState = "ready";
      return { ok: true, state: "ready", cached: true };
    }
    let result;
    try {
      result = await cmRefreshCatalog(resolution.path, {});
    } catch (error) {
      result = { ok: false, error: String((error && error.message) || error) };
    }
    if (!result.ok) {
      this.commandModeState = cmClassifyCatalogFailure({ ...result, binaryMissing });
      this.commandModeSyncRunCommands();
      return { ok: false, state: this.commandModeState, error: result.error };
    }
    this.commandModeCatalog = result.catalog;
    this.commandModeFingerprint = fingerprint;
    this.commandModeState = "ready";
    this.commandModeMissingBob = null;
    this.commandModeSyncRunCommands();
    void this.commandModePersist();
    return { ok: true, state: "ready" };
  }

  async commandModePersist() {
    try {
      await this.saveData({
        settings: this.settings,
        catalogCache: { fingerprint: this.commandModeFingerprint, catalog: this.commandModeCatalog },
      });
    } catch (error) {
      // Persistence is best effort.
    }
  }

  commandModeSyncRunCommands() {
    if (!this.commandModeRunner) return;
    const entries = cmCommandPaletteEntries(this.commandModeCatalog);
    for (const entry of entries) {
      const title = entry.title || entry.id;
      const spec = {
        id: "run-" + entry.id,
        name: "Bob: " + title,
        callback: () => {
          void this.commandModeRunner.run([...entry.path], {
            entryId: entry.id,
            trigger: "command",
            title,
          });
        },
      };
      try {
        cmAddCommand(this, spec);
      } catch (error) {
        // One bad row must not block the rest.
      }
    }
  }

  commandModeStartStatusChip() {
    if (typeof this.addStatusBarItem !== "function") return;
    try {
      this.commandModeStatusEl = this.addStatusBarItem();
      if (!this.commandModeStatusEl) return;
      this.commandModeStatusEl.addClass("bob-cmd-chip");
      this.commandModeStatusEl.style.display = "none";
      this.commandModeStatusEl.addEventListener("keydown", (event) => {
        if (event && (event.key === "Enter" || event.key === " ")) {
          event.preventDefault();
          const active = this.commandModeRunner && this.commandModeRunner.activeRecords();
          const newest = active && active[active.length - 1];
          if (newest) void this.commandModeOpenOutput(newest.id);
        }
      });
      this.commandModeRefreshStatusChip();
      this.commandModeStatusTimer = setInterval(() => this.commandModeRefreshStatusChip(), 250);
      if (this.commandModeStatusTimer && typeof this.commandModeStatusTimer.unref === "function") this.commandModeStatusTimer.unref();
    } catch (error) {
      this.commandModeStatusEl = null;
    }
  }

  commandModeRefreshStatusChip(nowMs = Date.now()) {
    const runner = this.commandModeRunner;
    if (!runner || !this.commandModeStatusEl) return { visible: false, runs: 0 };
    return cmRenderStatusChip(
      this.commandModeStatusEl,
      runner.activeRecords(),
      nowMs,
      (runId) => this.commandModeOpenOutput(runId),
      (runId) => this.commandModeProgressText(runId),
    );
  }

  commandModeProgressText(runId) {
    const runner = this.commandModeRunner;
    if (!runner) return "";
    let fd = null;
    try {
      const file = cmRunFilePaths(runner.runsDir(), String(runId || ""), runner.pathModule()).out;
      const fsModule = runner.fs();
      const size = fsModule.statSync(file).size;
      const length = Math.min(8192, size);
      const bytes = Buffer.alloc(length);
      fd = fsModule.openSync(file, "r");
      fsModule.readSync(fd, bytes, 0, length, Math.max(0, size - length));
      const lines = cmStripAnsi(bytes.toString("utf8")).split(/\r?\n/).map((line) => line.trim()).filter(Boolean);
      return lines[lines.length - 1] || "";
    } catch (error) {
      return "";
    } finally {
      if (fd !== null) {
        try { runner.fs().closeSync(fd); } catch (error) { /* Best effort. */ }
      }
    }
  }

  async commandModeSaveAllMarkdown() {
    const workspace = this.app && this.app.workspace;
    if (!workspace || typeof workspace.iterateAllLeaves !== "function") return { ok: true };
    const views = [];
    try {
      workspace.iterateAllLeaves((leaf) => {
        if (leaf && leaf.view instanceof MarkdownView && leaf.view.file) views.push(leaf.view);
      });
    } catch (error) {
      return { ok: true };
    }
    for (const view of views) {
      try {
        if (typeof view.save === "function") await view.save();
      } catch (error) {
        const filePath = view && view.file ? view.file.path : "note";
        return { ok: false, path: filePath };
      }
    }
    return { ok: true };
  }

  commandModeNotify(outcome) {
    try {
      const notice = { ...(outcome || {}) };
      const record = cmToastRun(notice);
      if (this.commandModePagerIsWatching(record.id || notice.runId)) {
        try { if (this.commandModePager) this.commandModePager.refresh(); }
        catch (error) { /* The pager may already be closing. */ }
        return null;
      }
      const source = [notice.reason, record.summary].filter(Boolean).join("\n");
      const actions = Array.isArray(notice.actions) ? [...notice.actions] : [];
      if (/bob not found/i.test(source) && !actions.some((action) => action.id === "open-settings")) {
        actions.push({ id: "open-settings", label: "Open settings" });
      }
      if (/(?:dirty.*paths?|paths?.*dirty|uncommitted\s+(?:edits|changes)|working tree.*dirty)/i.test(source)) {
        notice.reason = "Commit pending edits first";
        notice.actions = [...actions, { id: "sync-vault-retry", label: "Sync vault, then retry" }];
      } else {
        notice.actions = actions;
      }
      if (record.entry_id === "projects-sync" && notice.outcome === "completed") {
        notice.actions.push({ id: "run", label: "Reconcile tasks", entryId: "task-reconcile", argv: ["task", "reconcile"] });
      }
      const sticky = notice.outcome === "failed" || notice.outcome === "unknown";
      const stickyKey = String(record.entry_id || notice.entryId || notice.runId || "bob");
      if (sticky && this.commandModeStickyNotices) {
        const previous = this.commandModeStickyNotices.get(stickyKey);
        try { if (previous && typeof previous.hide === "function") previous.hide(); }
        catch (error) { /* A prior notice may already be closed. */ }
      }
      const fragment = cmCreateToastFragment(
        notice,
        (action, card) => this.commandModeRunToastAction(action, card),
        (runId) => this.commandModeOpenOutput(runId),
      );
      if (!fragment) {
        new Notice(cmToastSummary(notice), cmToastDuration(notice));
        return null;
      }
      const card = new Notice(fragment, cmToastDuration(notice));
      if (sticky && this.commandModeStickyNotices) this.commandModeStickyNotices.set(stickyKey, card);
      this.commandModeMaybeNotifyOS(notice);
      return card;
    } catch (error) {
      // Headless or unloaded: the record already carries the truth.
      return null;
    }
  }

  commandModeMaybeNotifyOS(outcome) {
    const record = cmToastRun(outcome);
    if (this.settings.osNotifications === false || Number(record.duration_ms) <= 15000) return false;
    try {
      if (typeof document !== "undefined" && typeof document.hasFocus === "function" && document.hasFocus()) return false;
      if (typeof Notification !== "function") return false;
      const title = cmToastTitle(outcome) + " · " + String(outcome.outcome || "completed");
      const notification = new Notification(title, { body: cmToastSummary(outcome) });
      notification.onclick = () => {
        try { if (typeof window !== "undefined" && typeof window.focus === "function") window.focus(); }
        catch (error) { /* The shell may not expose focus. */ }
        void this.commandModeOpenOutput(record.id || outcome.runId);
      };
      return true;
    } catch (error) {
      // OS notification APIs can be unavailable or denied; the in-app toast remains.
      return false;
    }
  }

  async commandModeRunToastAction(action, outcome = {}) {
    if (!action || !action.id) return { ok: false, reason: "unknown action" };
    const record = cmToastRun(outcome);
    const runner = this.commandModeRunner;
    switch (action.id) {
      case "output":
        return this.commandModeOpenOutput(record.id || outcome.runId);
      case "retry":
        return this.commandModeRerun(record);
      case "copy": {
        try {
          const clipboard = typeof navigator !== "undefined" && navigator.clipboard;
          if (!clipboard || typeof clipboard.writeText !== "function") return { ok: false, reason: "clipboard unavailable" };
          await clipboard.writeText(cmToastArgv(outcome));
          return { ok: true };
        } catch (error) {
          return { ok: false, reason: String((error && error.message) || error) };
        }
      }
      case "open-vault-note": {
        const workspace = this.app && this.app.workspace;
        if (!action.path || !workspace || typeof workspace.openLinkText !== "function") return { ok: false, reason: "note opener unavailable" };
        try { await workspace.openLinkText(String(action.path), "", false); return { ok: true }; }
        catch (error) { return { ok: false, reason: String((error && error.message) || error) }; }
      }
      case "open-settings": {
        try {
          const setting = this.app && this.app.setting;
          if (setting && typeof setting.open === "function") setting.open();
          if (setting && typeof setting.openTabById === "function") setting.openTabById("bob-command-mode");
          return { ok: Boolean(setting) };
        } catch (error) { return { ok: false, reason: String((error && error.message) || error) }; }
      }
      case "run":
        if (!runner || !Array.isArray(action.argv)) return { ok: false, reason: "runner unavailable" };
        return runner.run(action.argv, { entryId: action.entryId, title: action.label, trigger: "toast-action" });
      case "rerun-with-carry":
        return this.commandModeRerun(record, { carry: action.carry, preview: false });
      case "sync-vault-retry": {
        if (!runner) return { ok: false, reason: "runner unavailable" };
        const synced = await runner.run(["vault-sync", "run"], { entryId: "vault-sync", title: "Sync vault", trigger: "toast-action" });
        if (!synced || synced.outcome !== "completed") return synced;
        return this.commandModeRerun(record);
      }
      case "reload-plugins": {
        const plugins = this.app && this.app.plugins;
        if (!plugins || typeof plugins.disablePlugin !== "function" || typeof plugins.enablePlugin !== "function") {
          return { ok: false, reason: "plugin reload unavailable" };
        }
        const ids = Array.isArray(action.pluginIds) ? [...action.pluginIds] : [];
        const own = ids.filter((id) => id !== "bob-command-mode");
        if (ids.includes("bob-command-mode")) own.push("bob-command-mode");
        try {
          for (const id of own) {
            await plugins.disablePlugin(id);
            await plugins.enablePlugin(id);
          }
          return { ok: true, pluginIds: own };
        } catch (error) { return { ok: false, reason: String((error && error.message) || error) }; }
      }
      default:
        return { ok: false, reason: "unknown action: " + action.id };
    }
  }

  commandModeRerun(record, options = {}) {
    const runner = this.commandModeRunner;
    const current = record || (runner && runner.newestRecord());
    if (!runner || !current || !Array.isArray(current.argv)) return Promise.resolve({ ok: false, reason: "no command to rerun" });
    let words = [...current.argv];
    if (words.length && (words[0] === "bob" || words[0] === current.bob_path || /(?:^|\/)bob$/.test(String(words[0])))) words.shift();
    const entry = current.entry_id ? cmEntryById(runner.catalog(), current.entry_id) : null;
    if (entry && Array.isArray(entry.path) && entry.path.every((word, index) => words[index] === word)) {
      let rest = words.slice(entry.path.length);
      const previewFlags = Array.isArray(entry.preview) ? new Set(entry.preview.map(String)) : new Set();
      rest = rest.filter((word) => !previewFlags.has(String(word)));
      if (Array.isArray(entry.fixed)) {
        let cursor = 0;
        for (const fixed of entry.fixed) {
          const index = rest.indexOf(String(fixed), cursor);
          if (index >= 0) {
            rest.splice(index, 1);
            cursor = index;
          }
        }
      }
      words = [...entry.path, ...rest];
    }
    const carry = Array.isArray(options.carry) ? options.carry.map(String) : [];
    words.push(...carry);
    const preview = options.preview === undefined ? Boolean(current.preview) : Boolean(options.preview);
    return runner.run(words, {
      entryId: current.entry_id || undefined,
      title: current.title || undefined,
      trigger: "retry",
      preview,
    });
  }

  commandModeFireEvent(name, payload) {
    try {
      const workspace = this.app && this.app.workspace;
      if (workspace && typeof workspace.trigger === "function") workspace.trigger(name, payload);
    } catch (error) {
      // Event delivery must never break finalization.
    }
  }

  commandModeOnWorkspaceEvent(name, callback) {
    try {
      const workspace = this.app && this.app.workspace;
      if (workspace && typeof workspace.on === "function") {
        const ref = workspace.on(name, callback);
        return () => {
          try {
            if (typeof workspace.offref === "function") workspace.offref(ref);
          } catch (error) {
            // Unsubscribe is best effort.
          }
        };
      }
    } catch (error) {
      // No workspace: no subscription.
    }
    return () => {};
  }

  commandModeOpenSheet() {
    if (this.commandModeSheet && this.commandModeSheet.sheetOpen) {
      try { this.commandModeSheet.refocusInput(); } catch (error) { /* Best effort. */ }
      return { ok: true, focused: true };
    }
    try {
      const modal = new CommandModeSheetModal(this.app, this, {});
      this.commandModeSheet = modal;
      modal.open();
      return { ok: true, opened: true };
    } catch (error) {
      return { ok: false, reason: String((error && error.message) || error) };
    }
  }

  commandModeSheetIsWatching(runId) {
    const sheet = this.commandModeSheet;
    if (!sheet || !runId) return false;
    if (sheet.sheetOpen === false || sheet.stage !== "output") return false;
    return String(sheet.outputRunId) === String(runId) || String(sheet.previewRunId) === String(runId);
  }

  commandModePagerIsWatching(runId) {
    if (this.commandModeSheetIsWatching(runId)) return true;
    const pager = this.commandModePager;
    if (!pager || !runId) return false;
    if (pager.pagerOpen === false) return false;
    if (String(pager.runId) !== String(runId)) return false;
    try {
      if (typeof document !== "undefined" && typeof document.hasFocus === "function" && !document.hasFocus()) return false;
    } catch (error) {
      // Headless tests without a document still count as watching when the pager is open.
    }
    return true;
  }

  commandModeShowLastOutput() {
    const runner = this.commandModeRunner;
    const newest = runner && typeof runner.newestRecord === "function" ? runner.newestRecord() : null;
    if (!newest) {
      try { new Notice("No command output yet"); } catch (error) { /* Headless. */ }
      return { ok: false, reason: "no command output yet" };
    }
    return this.commandModeOpenOutput(newest.id);
  }

  commandModeOpenPath(filePath) {
    const runner = this.commandModeRunner;
    let shell = null;
    try {
      const electron = require("electron");
      shell = electron && electron.shell ? electron.shell : null;
    } catch (error) {
      shell = null;
    }
    const opener = (runner && runner.deps && runner.deps.shellOpenPath) ||
      (shell && shell.openPath ? (target) => shell.openPath(target) : null);
    if (!opener) return { ok: false, reason: "no file opener" };
    try {
      const result = opener(filePath);
      if (result && typeof result.then === "function") {
        return result.then(() => ({ ok: true })).catch((error) => ({ ok: false, reason: String((error && error.message) || error) }));
      }
      return { ok: true };
    } catch (error) {
      return { ok: false, reason: String((error && error.message) || error) };
    }
  }

  commandModeOpenOutput(runId) {
    const runner = this.commandModeRunner;
    if (!runner) return { ok: false, reason: "command mode is not loaded" };
    const id = String(runId || "");
    if (!id) return { ok: false, reason: "run not found" };
    const record = cmPagerFindRecord(runner, id);
    if (!record) return { ok: false, reason: "run not found" };
    try {
      if (this.commandModePager && this.commandModePager.pagerOpen) {
        this.commandModePager.showRun(id);
        return { ok: true, runId: id };
      }
      const modal = new CommandModePagerModal(this.app, this, { runId: id });
      this.commandModePager = modal;
      modal.open();
      return { ok: true, runId: id };
    } catch (error) {
      return { ok: false, reason: String((error && error.message) || error) };
    }
  }
}

class BobCommandModeSettingTab extends PluginSettingTab {
  constructor(app, plugin) {
    super(app, plugin);
    this.plugin = plugin;
  }

  display() {
    const { containerEl } = this;
    containerEl.empty();
    new Setting(containerEl)
      .setName("bob path")
      .setDesc("Find bob in its usual install locations or on PATH; set an explicit path to override.")
      .addText((text) => {
        text.setPlaceholder("Auto (blank)").setValue(this.plugin.settings.bobPath || "");
        text.onChange(async (value) => {
          this.plugin.settings.bobPath = String(value || "").trim();
          await this.plugin.commandModePersist();
          void this.plugin.commandModeRefreshCatalog("force");
        });
        return text;
      });
    new Setting(containerEl)
      .setName("OS notifications")
      .setDesc("Notify on long finished runs while Obsidian is unfocused.")
      .addToggle((toggle) => {
        toggle.setValue(this.plugin.settings.osNotifications !== false);
        toggle.onChange(async (value) => {
          this.plugin.settings.osNotifications = Boolean(value);
          await this.plugin.commandModePersist();
        });
        return toggle;
      });
    new Setting(containerEl)
      .setName("Keep runs")
      .setDesc("Retain at most this many runs in history.")
      .addText((text) => {
        text.setPlaceholder(String(CM_DEFAULT_KEEP_RUNS)).setValue(String(this.plugin.settings.keepRuns ?? ""));
        text.onChange(async (value) => {
          const parsed = Number.parseInt(String(value || "").trim(), 10);
          if (Number.isFinite(parsed) && parsed >= 0) {
            this.plugin.settings.keepRuns = parsed;
            if (this.plugin.commandModeRunner) this.plugin.commandModeRunner.deps.keepRuns = parsed;
            await this.plugin.commandModePersist();
          }
        });
        return text;
      });
    new Setting(containerEl)
      .setName("Keep days")
      .setDesc("Retain runs younger than this many days.")
      .addText((text) => {
        text.setPlaceholder(String(CM_DEFAULT_KEEP_DAYS)).setValue(String(this.plugin.settings.keepDays ?? ""));
        text.onChange(async (value) => {
          const parsed = Number.parseInt(String(value || "").trim(), 10);
          if (Number.isFinite(parsed) && parsed >= 0) {
            this.plugin.settings.keepDays = parsed;
            if (this.plugin.commandModeRunner) this.plugin.commandModeRunner.deps.keepDays = parsed;
            await this.plugin.commandModePersist();
          }
        });
        return text;
      });
  }
}
// ---- src/110-toasts.js ----
// Bob Command Mode: outcome toast cards and their action strip.

const CM_TOAST_META = {
  completed: { glyph: "✓", label: "Completed", duration: 5000 },
  attention: { glyph: "◐", label: "Needs attention", duration: 8000 },
  failed: { glyph: "✗", label: "Failed", duration: 0 },
  unknown: { glyph: "?", label: "Unknown · log preserved", duration: 0 },
  stopped: { glyph: "■", label: "Stopped", duration: 5000 },
};

function cmToastRun(outcome = {}) {
  return outcome.record && typeof outcome.record === "object" ? outcome.record : {};
}

function cmToastDuration(outcome = {}) {
  const state = CM_TOAST_META[outcome.outcome] ? outcome.outcome : "unknown";
  return CM_TOAST_META[state].duration;
}

function cmToastSummary(outcome = {}) {
  const record = cmToastRun(outcome);
  const source = outcome.reason || record.summary || outcome.summary || "Done";
  const lines = cmStripAnsi(source).split(/\r?\n/).map((line) => line.trim()).filter(Boolean);
  if (lines.length <= 2) return lines.join(" · ") || "Done";
  return lines.slice(0, 2).join(" · ") + " …";
}

function cmToastTitle(outcome = {}) {
  const record = cmToastRun(outcome);
  return String(record.title || outcome.title || record.entry_id || outcome.entryId || "bob");
}

function cmToastArgv(outcome = {}) {
  const record = cmToastRun(outcome);
  const argv = Array.isArray(record.argv) ? [...record.argv] : [];
  if (argv.length && (argv[0] === "bob" || /(?:^|\/)bob$/.test(String(argv[0])))) argv.shift();
  return cmFormatArgv(["bob", ...argv]);
}

function cmToastActions(outcome = {}) {
  const actions = Array.isArray(outcome.actions) ? outcome.actions.filter((action) => action && action.label) : [];
  actions.push({ id: "output", label: "Output" });
  actions.push({ id: "retry", label: "Retry" });
  actions.push({ id: "copy", label: "Copy" });
  return actions;
}

function cmToastNode(tag, className, text) {
  const element = document.createElement(tag);
  if (className) element.className = className;
  if (text !== undefined) element.textContent = String(text);
  return element;
}

function cmCreateToastFragment(outcome = {}, onAction = () => {}, onOutput = () => {}) {
  if (typeof document === "undefined" || !document.createDocumentFragment) return null;
  const state = CM_TOAST_META[outcome.outcome] ? outcome.outcome : "unknown";
  const meta = CM_TOAST_META[state];
  const fragment = document.createDocumentFragment();
  const card = cmToastNode("section", "bob-cmd-toast is-" + state);
  card.setAttribute("role", "status");
  card.setAttribute("aria-live", state === "failed" || state === "unknown" ? "assertive" : "polite");

  const header = cmToastNode("div", "bob-cmd-toast-header");
  const mark = cmToastNode("span", "bob-cmd-toast-mark", meta.glyph);
  mark.setAttribute("aria-hidden", "true");
  const title = cmToastNode("span", "bob-cmd-toast-title", cmToastTitle(outcome));
  const duration = cmToastNode("span", "bob-cmd-toast-duration", cmFormatDuration(cmToastRun(outcome).duration_ms));
  header.append(mark, title, duration);
  card.appendChild(header);

  const body = cmToastNode("div", "bob-cmd-toast-body");
  const summary = cmToastNode("div", "bob-cmd-toast-summary", cmToastSummary(outcome));
  const argv = cmToastNode("code", "bob-cmd-toast-argv", cmToastArgv(outcome));
  body.append(summary, argv);
  body.addEventListener("click", (event) => {
    if (event && event.defaultPrevented) return;
    onOutput(cmToastRun(outcome).id || outcome.runId);
  });
  card.appendChild(body);

  const actions = cmToastNode("div", "bob-cmd-toast-actions");
  for (const action of cmToastActions(outcome)) {
    const button = cmToastNode("button", "bob-cmd-toast-action", action.label);
    button.type = "button";
    button.setAttribute("data-action-id", action.id || "");
    button.addEventListener("click", (event) => {
      if (event) {
        event.preventDefault();
        event.stopPropagation();
      }
      onAction(action, outcome);
    });
    actions.appendChild(button);
  }
  card.appendChild(actions);
  fragment.appendChild(card);
  return fragment;
}
// ---- src/120-status-chip.js ----
// Bob Command Mode: live status-bar chip. Runner state stays authoritative.

function cmRenderStatusChip(element, records, nowMs = Date.now(), onOpen = () => {}, progressFor = () => "") {
  if (!element) return { visible: false, runs: 0 };
  const active = (Array.isArray(records) ? records : []).filter((record) => record && (record.outcome === "running" || record.outcome === "queued"));
  if (!active.length) {
    element.style.display = "none";
    element.classList.remove("is-overdue");
    element.textContent = "";
    element.removeAttribute("title");
    return { visible: false, runs: 0 };
  }
  const ages = active.map((record) => Math.max(0, nowMs - (Date.parse(record.started_at) || nowMs)));
  if (ages.every((age) => age < 400)) {
    element.style.display = "none";
    element.classList.remove("is-overdue");
    element.textContent = "";
    element.removeAttribute("title");
    return { visible: false, runs: active.length };
  }
  const longest = Math.max(...ages);
  const overdue = active.some((record, index) => record.overdue || (
    record.effect !== "reads" && Number(record.budget_secs) > 0 && ages[index] >= Number(record.budget_secs) * 1000
  ));
  const overdueRecord = active.find((record, index) => record.overdue || (
    record.effect !== "reads" && Number(record.budget_secs) > 0 && ages[index] >= Number(record.budget_secs) * 1000
  ));
  const newest = active[active.length - 1];
  const name = active.length === 1 ? String(newest.title || newest.entry_id || "bob") : "bob ×" + active.length;
  element.style.display = "";
  element.classList.toggle("is-overdue", overdue);
  const budgetMins = overdueRecord ? Math.max(1, Math.round(Number(overdueRecord.budget_secs) / 60)) : 0;
  element.textContent = overdue
    ? name + " · still running past ~" + budgetMins + " min"
    : name + " · " + cmFormatClock(longest);
  const detail = active.map((record) => {
    const argv = Array.isArray(record.argv) ? [...record.argv] : [];
    if (argv.length && (argv[0] === "bob" || /(?:^|\/)bob$/.test(String(argv[0])))) argv.shift();
    const progress = String(progressFor(record.id) || "").trim();
    return [cmFormatArgv(["bob", ...argv]), progress ? "Last: " + progress : ""].filter(Boolean).join("\n");
  }).join("\n\n");
  element.setAttribute("title", detail);
  element.setAttribute("aria-label", "Open output for " + name);
  element.setAttribute("role", "button");
  element.setAttribute("tabindex", "0");
  element.onclick = () => onOpen(newest.id);
  return { visible: true, runs: active.length, overdue, runId: newest.id };
}
// ---- src/130-adapters.js ----
// Bob Command Mode: catalog-keyed outcome adapters. These stay pure: action
// descriptors carry data, and the plugin decides how to present and execute it.

function cmAdapterJson(text) {
  const source = String((text && text.stdout) || "").trim();
  if (!source) return null;
  try {
    return JSON.parse(source);
  } catch (error) {
    const start = source.indexOf("{");
    const end = source.lastIndexOf("}");
    if (start < 0 || end <= start) return null;
    try { return JSON.parse(source.slice(start, end + 1)); }
    catch (ignored) { return null; }
  }
}

function cmAdapterAction(id, label, extra = {}) {
  return { id, label, ...extra };
}

function cmAdapterRefCreate(run, text) {
  const source = String((text && text.stdout) || "");
  const queued = source.match(/queued:\s*(.+?)\s*\(([^)]*)\)/i);
  if (queued) {
    const detail = queued[2].replace(/^\s*[^:]+:\s*/, "").trim();
    return {
      outcome: "attention",
      summary: detail ? "Queued — " + detail : "Queued for intake",
      actions: [cmAdapterAction("run", "Scan intake", { entryId: "ref-scan-intake", argv: ["ref", "scan"] })],
    };
  }
  const ingested = source.match(/ingested:\s*.+?\s+→\s+([^\r\n]+)/i);
  if (ingested) {
    const note = ingested[1].replace(/\s+(?:·\s+task\s+→|\(adopted\)).*$/i, "").trim();
    return {
      outcome: "completed",
      summary: "Added " + note,
      actions: [cmAdapterAction("open-vault-note", "Open note", { path: note })],
    };
  }
  return null;
}

function cmAdapterRefScan(run, text) {
  const report = cmAdapterJson(text);
  let held = report && report.summary ? Number(report.summary.held) || 0 : 0;
  if (!held) {
    const match = String((text && text.stdout) || "").match(/\b(\d+)\s+held\b|(?:pdfs?_held|pdf_markers_held|held)\s*:\s*(\d+)/i);
    if (match) held = Number(match[1] || match[2]) || 0;
  }
  if (held > 0) return { outcome: "attention", summary: held + " PDF writes held" };
  const combined = String((text && text.stdout) || "") + "\n" + String((text && text.stderr) || "");
  if (run.exitCode === 1 && /still\s+queued/i.test(combined)) {
    return { outcome: "attention", summary: "Intake is still queued" };
  }
  return null;
}

function cmAdapterVaultSync(run, text) {
  const stdout = String((text && text.stdout) || "").trim();
  const stderr = String((text && text.stderr) || "").trim();
  if (run.exitCode === 0 && !stdout && !stderr) {
    return { outcome: "attention", summary: "Skipped — another bob maintenance run holds the lock", retry: true };
  }
  const match = (stdout + "\n" + stderr).match(/[^\r\n]*(?:conflict|_conflicts\/)[^\r\n]*/i);
  if (match) {
    return {
      outcome: "attention",
      summary: cmLastMeaningfulLine(match[0]) || "Sync conflict needs review",
      actions: [cmAdapterAction("open-vault-note", "Open conflict log", { path: "_conflicts/sync_conflicts.md" })],
    };
  }
  return null;
}

function cmAdapterJsonWrite(run, text) {
  const result = cmAdapterJson(text);
  if (!result || typeof result !== "object") return null;
  const code = String(result.code || "");
  const message = String(result.message || "").trim();
  if (result.ok === false) {
    if (code === "unchanged") return { outcome: "attention", summary: message || "Already up to date" };
    return {
      outcome: "failed",
      summary: message || "Command failed",
      ...(code === "lock_busy" ? { retry: true } : {}),
    };
  }
  if (result.ok !== true) return null;
  const names = [result.hidden, result.unhidden].find(Array.isArray)
    ? [result.hidden, result.unhidden].find(Array.isArray).join(", ")
    : (result.name ? String(result.name) : "");
  const entryId = String(run.entry_id || "");
  const verb = /(?:themes|relations)-hide$/.test(entryId) ? "Hid"
    : /(?:themes|relations)-unhide$/.test(entryId) ? "Unhid"
      : /themes-color$/.test(entryId) ? "Pinned" : "Updated";
  return { outcome: "completed", summary: names ? verb + " " + names : message || "Updated" };
}

function cmAdapterPluginsSync(run, text) {
  const result = cmAdapterJson(text);
  if (!result || typeof result !== "object" || result.ok !== true || !Array.isArray(result.plugins)) return null;
  const changed = [];
  let dirty = 0;
  for (const plugin of result.plugins) {
    if (!plugin || typeof plugin.id !== "string" || !Array.isArray(plugin.files)) continue;
    if (plugin.files.some((file) => file && ["created", "updated", "forced"].includes(file.action))) changed.push(plugin.id);
    dirty += plugin.files.filter((file) => file && file.action === "skipped_dirty").length;
  }
  const actions = changed.length
    ? [cmAdapterAction("reload-plugins", "Reload " + changed.length + " plugin" + (changed.length === 1 ? "" : "s"), { pluginIds: changed })]
    : [];
  if (dirty > 0) {
    return {
      outcome: "attention",
      summary: changed.length
        ? "Deployed " + changed.length + ": " + changed.join(", ") + " · " + dirty + " dirty file" + (dirty === 1 ? " left alone" : "s left alone")
        : dirty + " dirty file" + (dirty === 1 ? " left alone" : "s left alone"),
      actions,
    };
  }
  return {
    outcome: "completed",
    summary: changed.length ? "Deployed " + changed.length + ": " + changed.join(", ") : "Plugins already up to date",
    actions,
  };
}

function cmAdapterTaskReroll(run, text) {
  if (!run.preview) return null;
  const result = cmAdapterJson(text);
  const source = String((text && text.stdout) || "");
  const seed = (result && result.seed) || (source.match(/\bseed\s+(0x[\da-f]+|\d+)/i) || [])[1];
  if (!seed) return null;
  return {
    carry: ["--seed", String(seed)],
    actions: [cmAdapterAction("rerun-with-carry", "Apply", { carry: ["--seed", String(seed)] })],
  };
}

function cmAdapterPomodoroStatus(run, text) {
  if (run.exitCode !== 0) return { outcome: "failed", summary: String((text && (text.err || text.out)) || "Pomodoro status failed").trim() };
  return { outcome: "completed", summary: String((text && text.out) || "").trim() || "No Pomodoro running" };
}

function cmAdapterCaptureSession(run, text) {
  const summary = String((text && (text.out || text.err)) || "").trim() || (run.exitCode === 0 ? "Pomodoro updated" : "Command refused");
  return { outcome: run.exitCode === 0 ? "completed" : "failed", summary };
}

function cmAdapterGkeepPull(run, text) {
  const result = cmAdapterJson(text);
  const source = String((text && text.stdout) || "");
  const pulled = result && Number(result.pulled ?? result.notes_pulled ?? result.imported);
  const saysEmpty = pulled === 0 || /\b0\s+(?:notes|items)\s+(?:pulled|imported)\b/i.test(source);
  if (run.exitCode === 0 && saysEmpty) return { outcome: "completed", summary: "Keep inbox already empty" };
  return null;
}

cmRegisterOutcomeAdapter("ref-create", cmAdapterRefCreate);
cmRegisterOutcomeAdapter("ref-scan", cmAdapterRefScan);
cmRegisterOutcomeAdapter("vault-sync", cmAdapterVaultSync);
cmRegisterOutcomeAdapter("json-write", cmAdapterJsonWrite);
cmRegisterOutcomeAdapter("plugins-sync", cmAdapterPluginsSync);
cmRegisterOutcomeAdapter("task-reroll", cmAdapterTaskReroll);
cmRegisterOutcomeAdapter("pomodoro-status", cmAdapterPomodoroStatus);
cmRegisterOutcomeAdapter("capture-session", cmAdapterCaptureSession);
cmRegisterOutcomeAdapter("gkeep-pull", cmAdapterGkeepPull);
// ---- src/140-ansi-and-links.js ----
// Bob Command Mode: streaming ANSI parser, JSON pretty-print, vault linkifier,
// interleave replay, pager copy/search/keys. Pure helpers; the pager view
// mounts them. Never innerHTML, never Markdown.

const CM_PAGER_LINE_PX = 19;
const CM_ANSI_FG = {
  30: "var(--text-muted)",
  31: "var(--color-red)",
  32: "var(--color-green)",
  33: "var(--color-yellow, var(--color-orange))",
  34: "var(--color-blue, var(--text-accent))",
  35: "var(--color-purple, var(--text-accent))",
  36: "var(--color-cyan, var(--color-blue, var(--text-accent)))",
  37: "var(--text-normal)",
  90: "var(--text-muted)",
  91: "var(--color-red)",
  92: "var(--color-green)",
  93: "var(--color-yellow, var(--color-orange))",
  94: "var(--color-blue, var(--text-accent))",
  95: "var(--color-purple, var(--text-accent))",
  96: "var(--color-cyan, var(--color-blue, var(--text-accent)))",
  97: "var(--text-normal)",
};
const CM_ANSI_BG = {
  40: "var(--text-muted)",
  41: "var(--color-red)",
  42: "var(--color-green)",
  43: "var(--color-yellow, var(--color-orange))",
  44: "var(--color-blue, var(--text-accent))",
  45: "var(--color-purple, var(--text-accent))",
  46: "var(--color-cyan, var(--color-blue, var(--text-accent)))",
  47: "var(--text-normal)",
};

function cmDefaultAnsiStyle() {
  return { bold: false, dim: false, italic: false, underline: false, fg: null, bg: null, muted: false };
}

function cmAnsiStylesEqual(left, right) {
  if (!left || !right) return false;
  return left.bold === right.bold && left.dim === right.dim && left.italic === right.italic &&
    left.underline === right.underline && left.fg === right.fg && left.bg === right.bg &&
    left.muted === right.muted;
}

function cmCreateAnsiParser() {
  return { leftover: "", style: cmDefaultAnsiStyle() };
}

function cmAnsi256Color(index) {
  const n = Number(index);
  if (!Number.isFinite(n) || n < 0) return null;
  if (n < 8) return CM_ANSI_FG[30 + n] || null;
  if (n < 16) return CM_ANSI_FG[90 + (n - 8)] || null;
  if (n >= 232) {
    const value = 8 + (n - 232) * 10;
    return "rgb(" + value + "," + value + "," + value + ")";
  }
  const cube = n - 16;
  const ramp = (part) => (part === 0 ? 0 : 55 + part * 40);
  const red = ramp(Math.floor(cube / 36));
  const green = ramp(Math.floor((cube % 36) / 6));
  const blue = ramp(cube % 6);
  return "rgb(" + red + "," + green + "," + blue + ")";
}

function cmApplySgr(style, params) {
  const next = { ...style };
  const codes = params.length ? params : [0];
  for (let index = 0; index < codes.length; index += 1) {
    const code = Number(codes[index]);
    if (!Number.isFinite(code) || code === 0) {
      next.bold = false;
      next.dim = false;
      next.italic = false;
      next.underline = false;
      next.fg = null;
      next.bg = null;
      next.muted = false;
      continue;
    }
    if (code === 1) next.bold = true;
    else if (code === 2) next.dim = true;
    else if (code === 3) next.italic = true;
    else if (code === 4) next.underline = true;
    else if (code === 22) { next.bold = false; next.dim = false; }
    else if (code === 23) next.italic = false;
    else if (code === 24) next.underline = false;
    else if (code === 39) next.fg = null;
    else if (code === 49) next.bg = null;
    else if (CM_ANSI_FG[code]) next.fg = CM_ANSI_FG[code];
    else if (CM_ANSI_BG[code]) next.bg = CM_ANSI_BG[code];
    else if (code === 38 || code === 48) {
      const slot = code === 38 ? "fg" : "bg";
      const mode = Number(codes[index + 1]);
      if (mode === 5 && codes[index + 2] !== undefined) {
        next[slot] = cmAnsi256Color(codes[index + 2]);
        index += 2;
      } else if (mode === 2 && codes[index + 4] !== undefined) {
        const red = Math.max(0, Math.min(255, Number(codes[index + 2]) || 0));
        const green = Math.max(0, Math.min(255, Number(codes[index + 3]) || 0));
        const blue = Math.max(0, Math.min(255, Number(codes[index + 4]) || 0));
        next[slot] = "rgb(" + red + "," + green + "," + blue + ")";
        index += 4;
      } else {
        index += 1;
      }
    }
  }
  return next;
}

function cmConsumeEscape(text) {
  if (!text || text[0] !== "\u001b") return { length: 0, incomplete: false };
  if (text.length === 1) return { length: 1, incomplete: true };
  const second = text[1];
  if (second === "[") {
    let index = 2;
    while (index < text.length) {
      const code = text.charCodeAt(index);
      if (code >= 64 && code <= 126) {
        const final = text[index];
        const body = text.slice(2, index);
        const params = final === "m"
          ? body.split(";").map((part) => (part === "" ? 0 : Number(part)))
          : [];
        return { length: index + 1, incomplete: false, sgr: final === "m", params };
      }
      index += 1;
    }
    return { length: text.length, incomplete: true };
  }
  if (second === "]") {
    for (let index = 2; index < text.length; index += 1) {
      if (text[index] === "\u0007") return { length: index + 1, incomplete: false };
      if (text[index] === "\u001b" && text[index + 1] === "\\") return { length: index + 2, incomplete: false };
    }
    return { length: text.length, incomplete: true };
  }
  if (second === "(" || second === ")") {
    if (text.length < 3) return { length: text.length, incomplete: true };
    return { length: 3, incomplete: false };
  }
  return { length: 2, incomplete: false };
}

function cmPushAnsiNode(nodes, text, style) {
  if (!text) return;
  const last = nodes[nodes.length - 1];
  if (last && cmAnsiStylesEqual(last.style, style)) last.text += text;
  else nodes.push({ text, style: { ...style } });
}

function cmParseAnsiChunk(parser, chunk) {
  const source = String((parser && parser.leftover) || "") + String(chunk || "");
  if (parser) parser.leftover = "";
  const nodes = [];
  let current = "";
  let index = 0;
  const styleOf = () => (parser && parser.style) || cmDefaultAnsiStyle();
  const flush = () => {
    cmPushAnsiNode(nodes, current, styleOf());
    current = "";
  };
  while (index < source.length) {
    if (source[index] === "\u001b") {
      const consumed = cmConsumeEscape(source.slice(index));
      if (consumed.incomplete) {
        if (parser) parser.leftover = source.slice(index);
        break;
      }
      flush();
      if (consumed.sgr && parser) parser.style = cmApplySgr(parser.style, consumed.params || []);
      index += consumed.length;
      continue;
    }
    current += source[index];
    index += 1;
  }
  flush();
  return nodes;
}

function cmParseAnsi(text) {
  const parser = cmCreateAnsiParser();
  return cmParseAnsiChunk(parser, text);
}

function cmAnsiStyleToCss(style) {
  if (!style) return "";
  const parts = [];
  if (style.bold) parts.push("font-weight:700");
  if (style.dim) parts.push("opacity:0.7");
  if (style.italic) parts.push("font-style:italic");
  if (style.underline) parts.push("text-decoration:underline");
  if (style.fg) parts.push("color:" + style.fg);
  if (style.bg) parts.push("background-color:" + style.bg);
  if (style.muted) parts.push("color:var(--text-muted)");
  return parts.join(";");
}

function cmNormalizePagerNewlines(text) {
  return String(text || "").replace(/\r\n/g, "\n").replace(/\r/g, "\n");
}

function cmBufferFrom(value) {
  if (value == null) {
    if (typeof Buffer !== "undefined" && typeof Buffer.alloc === "function") return Buffer.alloc(0);
    return { length: 0, slice() { return ""; }, subarray() { return ""; }, toString() { return ""; } };
  }
  if (typeof Buffer !== "undefined" && Buffer.isBuffer && Buffer.isBuffer(value)) return value;
  if (typeof Buffer !== "undefined" && typeof Buffer.from === "function") return Buffer.from(String(value), "utf8");
  const text = String(value);
  return {
    length: text.length,
    slice(start, end) { return text.slice(start, end); },
    subarray(start, end) { return text.slice(start, end); },
    toString() { return text; },
  };
}

function cmReplayInterleave(stdoutValue, stderrValue, interleave) {
  const stdout = cmBufferFrom(stdoutValue);
  const stderr = cmBufferFrom(stderrValue);
  const chunks = [];
  let outOff = 0;
  let errOff = 0;
  const pairs = Array.isArray(interleave) ? interleave : [];
  const take = (buffer, offset, count, stream) => {
    const end = Math.min(buffer.length, offset + Math.max(0, count));
    const slice = typeof buffer.subarray === "function" ? buffer.subarray(offset, end) : buffer.slice(offset, end);
    const text = typeof slice.toString === "function" ? slice.toString("utf8") : String(slice);
    if (text) chunks.push({ stream, text: cmNormalizePagerNewlines(text) });
    return end;
  };
  for (const pair of pairs) {
    const stream = pair && pair[0];
    const count = Number(pair && pair[1]) || 0;
    if (stream === "out") outOff = take(stdout, outOff, count, "out");
    else if (stream === "err") errOff = take(stderr, errOff, count, "err");
  }
  if (outOff < stdout.length) take(stdout, outOff, stdout.length - outOff, "out");
  if (errOff < stderr.length) take(stderr, errOff, stderr.length - errOff, "err");
  return chunks;
}

function cmTryParseJsonBody(text) {
  const source = cmStripAnsi(text).trim();
  if (!source || (source[0] !== "{" && source[0] !== "[")) return null;
  try {
    const value = JSON.parse(source);
    if (value === null || typeof value !== "object") return null;
    return value;
  } catch (error) {
    return null;
  }
}

function cmJsonPrettyNodes(value) {
  const nodes = [];
  const push = (text, kind) => {
    if (!text) return;
    const style = kind === "key" ? { ...cmDefaultAnsiStyle(), muted: true } : cmDefaultAnsiStyle();
    const last = nodes[nodes.length - 1];
    if (last && last.kind === kind && cmAnsiStylesEqual(last.style, style)) last.text += text;
    else nodes.push({ text, style, kind });
  };
  const walk = (item, level) => {
    const pad = "  ".repeat(level);
    if (item !== null && typeof item === "object") {
      const isArray = Array.isArray(item);
      const entries = isArray
        ? item.map((entry, index) => [index, entry])
        : Object.keys(item).map((key) => [key, item[key]]);
      push(isArray ? "[" : "{", "punct");
      if (!entries.length) {
        push(isArray ? "]" : "}", "punct");
        return;
      }
      push("\n", "punct");
      entries.forEach(([key, entry], index) => {
        push(pad + "  ", "punct");
        if (!isArray) {
          push(JSON.stringify(String(key)), "key");
          push(": ", "punct");
        }
        walk(entry, level + 1);
        if (index < entries.length - 1) push(",", "punct");
        push("\n", "punct");
      });
      push(pad + (isArray ? "]" : "}"), "punct");
      return;
    }
    if (typeof item === "string") push(JSON.stringify(item), "string");
    else if (typeof item === "number" || typeof item === "boolean") push(String(item), "value");
    else push("null", "value");
  };
  walk(value, 0);
  return nodes;
}

function cmMaybePrettyJsonChunks(chunks) {
  const list = Array.isArray(chunks) ? chunks : [];
  const stdout = list.filter((chunk) => chunk && chunk.stream === "out").map((chunk) => chunk.text).join("");
  const parsed = cmTryParseJsonBody(stdout);
  if (!parsed) return list;
  const stderr = list.filter((chunk) => chunk && chunk.stream === "err");
  return [{ stream: "out", nodes: cmJsonPrettyNodes(parsed) }, ...stderr];
}

function cmResolveLinkTarget(app, linkpath) {
  const pathOnly = String(linkpath || "").split("#")[0];
  if (!pathOnly) return null;
  try {
    const vault = app && app.vault;
    if (vault && typeof vault.getAbstractFileByPath === "function") {
      const file = vault.getAbstractFileByPath(pathOnly);
      if (file) return { path: file.path || pathOnly, file };
    }
  } catch (error) {
    // Vault lookup is best effort.
  }
  try {
    const cache = app && app.metadataCache;
    if (cache && typeof cache.getFirstLinkpathDest === "function") {
      const dest = cache.getFirstLinkpathDest(pathOnly, "");
      if (dest) return { path: dest.path || pathOnly, file: dest };
    }
  } catch (error) {
    // Cache lookup is best effort.
  }
  return null;
}

function cmPushLinkSpan(spans, span, app) {
  if (!span || span.end <= span.start) return;
  const resolved = cmResolveLinkTarget(app, span.linkpath);
  if (!resolved) return;
  spans.push({ ...span, path: resolved.path });
}

function cmFindWikiLinkSpans(text, app) {
  const spans = [];
  const regex = /\[\[([^\]|#\n]+)(?:#([^|\]]+))?(?:\|([^\]]+))?\]\]/g;
  let match;
  while ((match = regex.exec(String(text || "")))) {
    const target = match[1] + (match[2] ? "#" + match[2] : "");
    cmPushLinkSpan(spans, {
      start: match.index,
      end: match.index + match[0].length,
      text: match[3] || match[0],
      linkpath: target,
      href: target,
      line: null,
      kind: "wiki",
    }, app);
  }
  return spans;
}

function cmFindMdPathSpans(text, app) {
  const spans = [];
  const regex = /(?<![A-Za-z0-9_./-])((?:[A-Za-z0-9_.-]+\/)*[A-Za-z0-9_.-]+\.md)(?::(\d+)|(#[^\s\]|]+))?/g;
  let match;
  while ((match = regex.exec(String(text || "")))) {
    const line = match[2] ? Number(match[2]) : null;
    const hash = match[3] || "";
    cmPushLinkSpan(spans, {
      start: match.index,
      end: match.index + match[0].length,
      text: match[0],
      linkpath: match[1],
      href: match[1] + hash,
      line: Number.isFinite(line) ? line : null,
      kind: "path",
    }, app);
  }
  return spans;
}

function cmFindAbsolutePathSpans(text, app, vaultBase) {
  const prefix = String(vaultBase || "").replace(/\/+$/, "");
  if (!prefix) return [];
  const spans = [];
  const escaped = prefix.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const regex = new RegExp(escaped + "/((?:[^\\s]+/)*[^\\s]+\\.md)(?::(\\d+)|(#[^\\s\\]|]+))?", "g");
  let match;
  while ((match = regex.exec(String(text || "")))) {
    const line = match[2] ? Number(match[2]) : null;
    const hash = match[3] || "";
    cmPushLinkSpan(spans, {
      start: match.index,
      end: match.index + match[0].length,
      text: match[0],
      linkpath: match[1],
      href: match[1] + hash,
      line: Number.isFinite(line) ? line : null,
      kind: "absolute",
    }, app);
  }
  return spans;
}

function cmFindLinkSpans(text, options = {}) {
  const source = String(text || "");
  const app = options.app || null;
  const combined = [
    ...cmFindWikiLinkSpans(source, app),
    ...cmFindAbsolutePathSpans(source, app, options.vaultBase),
    ...cmFindMdPathSpans(source, app),
  ].sort((left, right) => left.start - right.start || right.end - left.end);
  const spans = [];
  let cursor = 0;
  for (const span of combined) {
    if (span.start < cursor) continue;
    spans.push(span);
    cursor = span.end;
  }
  return spans;
}

function cmLinkifyAnsiNodes(nodes, options = {}) {
  const result = [];
  for (const node of Array.isArray(nodes) ? nodes : []) {
    const text = String(node.text || "");
    const spans = cmFindLinkSpans(text, options);
    if (!spans.length) {
      result.push({ ...node });
      continue;
    }
    let cursor = 0;
    for (const span of spans) {
      if (span.start > cursor) result.push({ text: text.slice(cursor, span.start), style: node.style });
      result.push({
        text: text.slice(span.start, span.end),
        style: node.style,
        href: span.href,
        path: span.path,
        line: span.line,
      });
      cursor = span.end;
    }
    if (cursor < text.length) result.push({ text: text.slice(cursor), style: node.style });
  }
  return result;
}

function cmDecoratePagerChunks(chunks, options = {}) {
  const pretty = cmMaybePrettyJsonChunks(chunks);
  return pretty.map((chunk) => {
    if (chunk.nodes) {
      return { stream: chunk.stream || "out", nodes: cmLinkifyAnsiNodes(chunk.nodes, options) };
    }
    const parser = cmCreateAnsiParser();
    const ansi = cmParseAnsiChunk(parser, chunk.text || "");
    return { stream: chunk.stream || "out", nodes: cmLinkifyAnsiNodes(ansi, options) };
  });
}

function cmPagerVisibleText(chunks) {
  const parts = [];
  for (const chunk of Array.isArray(chunks) ? chunks : []) {
    if (Array.isArray(chunk.nodes)) {
      for (const node of chunk.nodes) parts.push(node.text || "");
    } else {
      parts.push(chunk.text || "");
    }
  }
  return parts.join("");
}

function cmPagerCopyOutput(chunks) {
  return cmStripAnsi(cmPagerVisibleText(chunks));
}

function cmPagerDisplayArgv(record) {
  const argv = Array.isArray(record && record.argv) ? [...record.argv] : [];
  if (argv.length && (argv[0] === "bob" || /(?:^|\/)bob$/.test(String(argv[0])))) argv.shift();
  return cmFormatArgv(["bob", ...argv]);
}

function cmPagerCopyCommand(record) {
  return cmPagerDisplayArgv(record);
}

function cmFormatStartTime(iso) {
  const date = new Date(iso);
  if (!Number.isFinite(date.getTime())) return "";
  return cmPad2(date.getHours()) + ":" + cmPad2(date.getMinutes()) + ":" + cmPad2(date.getSeconds());
}

function cmPagerStatusMeta(record, nowMs = Date.now(), queuedBehind = "") {
  const outcome = record && record.outcome ? record.outcome : "unknown";
  const exitLabel = typeof (record && record.exit_code) === "number" ? "exit " + record.exit_code : "";
  const started = Date.parse(record && record.started_at);
  const elapsed = Number.isFinite(started) ? Math.max(0, nowMs - started) : 0;
  if (outcome === "running") {
    return { glyph: "●", text: "running " + cmFormatClock(elapsed), className: "is-running" };
  }
  if (outcome === "queued") {
    const behind = queuedBehind ? "queued behind " + queuedBehind : "queued";
    return { glyph: "⧗", text: behind, className: "is-queued" };
  }
  if (outcome === "completed") {
    return { glyph: "✓", text: "completed · " + cmFormatDuration(record.duration_ms), className: "is-completed" };
  }
  if (outcome === "attention") {
    return { glyph: "◐", text: ["needs attention", exitLabel].filter(Boolean).join(" · "), className: "is-attention" };
  }
  if (outcome === "failed") {
    return { glyph: "✗", text: ["failed", exitLabel].filter(Boolean).join(" · "), className: "is-failed" };
  }
  if (outcome === "stopped") {
    return { glyph: "■", text: "stopped", className: "is-stopped" };
  }
  return { glyph: "?", text: "unknown", className: "is-unknown" };
}

function cmFindSearchMatches(text, query) {
  const source = String(text || "");
  const needle = String(query || "");
  if (!needle) return [];
  const matches = [];
  let from = 0;
  while (from <= source.length) {
    const index = source.indexOf(needle, from);
    if (index < 0) break;
    matches.push({ start: index, end: index + needle.length });
    from = index + Math.max(1, needle.length);
  }
  return matches;
}

function cmPagerHistoryIds(records) {
  return (Array.isArray(records) ? records : [])
    .map((record) => record && record.id)
    .filter(Boolean)
    .slice()
    .reverse();
}

function cmPagerHistoryState(records, runId) {
  const ids = cmPagerHistoryIds(records);
  const index = ids.indexOf(runId);
  return {
    ids,
    index,
    total: ids.length,
    label: index >= 0 && ids.length ? (index + 1) + " of " + ids.length : "",
    olderId: index >= 0 ? ids[index + 1] || null : null,
    newerId: index >= 0 ? ids[index - 1] || null : null,
  };
}

function cmPagerApplyScroll(scroll, action) {
  const view = Math.max(0, Number(scroll && scroll.view) || 0);
  const height = Math.max(0, Number(scroll && scroll.height) || 0);
  const max = Math.max(0, height - view);
  const half = Math.max(CM_PAGER_LINE_PX, Math.floor(view / 2) || CM_PAGER_LINE_PX * 8);
  let top = Number(scroll && scroll.top) || 0;
  if (action.delta === "line") top += action.dir * CM_PAGER_LINE_PX;
  else if (action.delta === "half") top += action.dir * half;
  else if (action.delta === "home") top = 0;
  else if (action.delta === "end") top = max;
  return Math.max(0, Math.min(max, top));
}

function cmDefaultPagerSearch() {
  return { mode: "off", query: "", matches: [], current: -1 };
}

function cmHandlePagerKey(event, state = {}) {
  if (!event) return { type: "none" };
  if (event.altKey) return { type: "none" };
  const key = event.key;
  const ctrl = Boolean(event.ctrlKey);
  const meta = Boolean(event.metaKey);
  const search = state.search || cmDefaultPagerSearch();
  if (search.mode === "editing") {
    if (key === "Escape") return { type: "search-cancel" };
    if (key === "Enter") return { type: "search-commit" };
    if (key === "Backspace") return { type: "search-backspace" };
    if (!ctrl && !meta && key.length === 1) return { type: "search-type", char: key };
    return { type: "none" };
  }
  if (state.stopConfirm) {
    if (key === "y" || key === "Y" || key === "Enter") return { type: "stop" };
    if (key === "Escape" || key === "n" || key === "N") return { type: "stop-cancel" };
    if (key === "q") return { type: "close" };
  }
  if ((ctrl || meta) && (key === "c" || key === "C")) {
    if (state.hasSelection) return { type: "none" };
    return { type: "stop-request" };
  }
  if (ctrl || meta) return { type: "none" };
  if (search.mode === "idle") {
    if (key === "n") return { type: "search-next" };
    if (key === "N") return { type: "search-prev" };
    if (key === "Escape") return { type: "search-cancel" };
  }
  switch (key) {
    case "j": return { type: "scroll", delta: "line", dir: 1 };
    case "k": return { type: "scroll", delta: "line", dir: -1 };
    case "d": return { type: "scroll", delta: "half", dir: 1 };
    case "u": return { type: "scroll", delta: "half", dir: -1 };
    case "g": return { type: "scroll", delta: "home" };
    case "G": return { type: "scroll", delta: "end" };
    case "/": return { type: "search-start" };
    case "w": return { type: "wrap" };
    case "y": return { type: "copy-output" };
    case "Y": return { type: "copy-command" };
    case "r": return { type: "rerun" };
    case "[": return { type: "history", dir: 1 };
    case "]": return { type: "history", dir: -1 };
    case ":": return { type: "back" };
    case "Escape": return { type: "escape" };
    case "q": return { type: "close" };
    default: return { type: "none" };
  }
}
// ---- src/150-pager.js ----
// Bob Command Mode: output pager view and standalone sheet-shaped modal.
// The sheet phase remounts the same view in its output stage.

function cmPagerEl(tag, className, text) {
  const element = document.createElement(tag);
  if (className) element.className = className;
  if (text !== undefined) element.textContent = String(text);
  return element;
}

function cmPagerHasSelection() {
  try {
    const selection = typeof window !== "undefined" && window.getSelection ? window.getSelection() : null;
    return Boolean(selection && String(selection.toString() || "").length);
  } catch (error) {
    return false;
  }
}

async function cmPagerWriteClipboard(text) {
  try {
    const clipboard = typeof navigator !== "undefined" && navigator.clipboard;
    if (!clipboard || typeof clipboard.writeText !== "function") return { ok: false, reason: "clipboard unavailable" };
    await clipboard.writeText(String(text || ""));
    return { ok: true };
  } catch (error) {
    return { ok: false, reason: String((error && error.message) || error) };
  }
}

function cmPagerReadCapped(fsModule, filePath, cap) {
  let fd = null;
  try {
    const size = fsModule.statSync(filePath).size;
    const length = Math.min(Math.max(0, cap), Math.max(0, size));
    const buffer = Buffer.alloc(length);
    fd = fsModule.openSync(filePath, "r");
    fsModule.readSync(fd, buffer, 0, length, 0);
    return { buffer, truncated: size > cap };
  } catch (error) {
    return { buffer: Buffer.alloc(0), truncated: false };
  } finally {
    if (fd !== null) {
      try { fsModule.closeSync(fd); } catch (error) { /* Best effort. */ }
    }
  }
}

function cmPagerQueuedBehind(runner) {
  if (!runner || !runner.live) return "";
  try {
    for (const live of runner.live.values()) {
      const record = live && live.record;
      if (record && record.outcome === "running" && record.effect !== "reads") {
        return record.title || record.entry_id || cmPagerDisplayArgv(record);
      }
    }
  } catch (error) {
    return "";
  }
  return "";
}

function cmPagerFindRecord(runner, runId) {
  if (!runner) return null;
  const id = String(runId || "");
  if (!id) return null;
  try {
    const live = runner.live && runner.live.get(id);
    if (live && live.record) return live.record;
  } catch (error) {
    // Fall through to the store.
  }
  try {
    const records = cmListRecords(runner.fs(), runner.runsDir());
    return records.find((record) => record && record.id === id) || null;
  } catch (error) {
    return null;
  }
}

function cmPagerLoadPayload(runner, runId) {
  const id = String(runId || "");
  if (!runner || !id) return null;
  let live = null;
  try { live = runner.live && runner.live.get(id); } catch (error) { live = null; }
  if (live && live.state) {
    return {
      record: live.record,
      stdout: Buffer.from(String(live.state.stdout || ""), "utf8"),
      stderr: Buffer.from(String(live.state.stderr || ""), "utf8"),
      truncated: Boolean(live.state.truncated || (live.record && live.record.truncated)),
      live: true,
    };
  }
  const record = cmPagerFindRecord(runner, id);
  if (!record) return null;
  const paths = cmRunFilePaths(runner.runsDir(), id, runner.pathModule());
  const out = cmPagerReadCapped(runner.fs(), paths.out, CM_MEM_CAP_BYTES);
  const err = cmPagerReadCapped(runner.fs(), paths.err, CM_MEM_CAP_BYTES);
  return {
    record,
    stdout: out.buffer,
    stderr: err.buffer,
    truncated: Boolean(record.truncated || out.truncated || err.truncated),
    live: false,
    paths,
  };
}

function cmBuildPagerView(payload, options = {}) {
  const record = (payload && payload.record) || {};
  const nowMs = typeof options.nowMs === "number" ? options.nowMs : Date.now();
  const rawChunks = Array.isArray(options.chunks)
    ? options.chunks
    : cmReplayInterleave(payload && payload.stdout, payload && payload.stderr, record.interleave);
  const chunks = cmDecoratePagerChunks(rawChunks, {
    app: options.app,
    vaultBase: options.vaultBase,
  });
  const history = options.history || cmPagerHistoryState(options.records || [], record.id);
  const search = options.search || cmDefaultPagerSearch();
  const visible = cmPagerVisibleText(chunks);
  if (search.mode !== "off" && search.query) search.matches = cmFindSearchMatches(visible, search.query);
  return {
    record,
    status: cmPagerStatusMeta(record, nowMs, options.queuedBehind || ""),
    argv: cmPagerDisplayArgv(record),
    started: cmFormatStartTime(record.started_at),
    history,
    stopVisible: record.outcome === "running",
    stopConfirm: Boolean(options.stopConfirm),
    wrap: Boolean(options.wrap),
    truncated: Boolean(payload && payload.truncated),
    search,
    chunks,
    visible,
  };
}

function cmPagerMarkSearch(text, offset, search) {
  const source = String(text || "");
  if (!search || search.mode === "off" || !search.matches || !search.matches.length) {
    return [{ text: source, hit: false, current: false }];
  }
  const parts = [];
  let cursor = 0;
  const start = offset;
  const end = offset + source.length;
  for (let index = 0; index < search.matches.length; index += 1) {
    const match = search.matches[index];
    if (match.end <= start || match.start >= end) continue;
    const localStart = Math.max(0, match.start - start);
    const localEnd = Math.min(source.length, match.end - start);
    if (localStart > cursor) parts.push({ text: source.slice(cursor, localStart), hit: false, current: false });
    parts.push({ text: source.slice(localStart, localEnd), hit: true, current: index === search.current });
    cursor = localEnd;
  }
  if (cursor < source.length) parts.push({ text: source.slice(cursor), hit: false, current: false });
  return parts.length ? parts : [{ text: source, hit: false, current: false }];
}

function cmRenderPagerText(parent, node, offset, search, handlers) {
  const pieces = cmPagerMarkSearch(node.text || "", offset, search);
  for (const piece of pieces) {
    let el = cmPagerEl(node.href ? "a" : "span", "bob-cmd-ansi");
    if (node.kind === "key") el.classList.add("bob-cmd-json-key");
    if (node.href) {
      el.classList.add("bob-cmd-link");
      el.setAttribute("href", node.href);
      el.setAttribute("data-link-path", node.path || node.href);
      if (node.line != null) el.setAttribute("data-link-line", String(node.line));
      el.addEventListener("click", (event) => {
        if (event) {
          event.preventDefault();
          event.stopPropagation();
        }
        if (typeof handlers.onLink === "function") {
          handlers.onLink({
            path: node.path || node.href,
            href: node.href,
            line: node.line,
            newLeaf: Boolean(event && (event.metaKey || event.ctrlKey)),
          });
        }
      });
    }
    const css = cmAnsiStyleToCss(node.style);
    if (css) el.setAttribute("style", css);
    if (piece.hit) {
      const mark = cmPagerEl("mark", "bob-cmd-search-hit" + (piece.current ? " is-current" : ""), piece.text);
      el.appendChild(mark);
    } else {
      el.textContent = piece.text;
    }
    parent.appendChild(el);
  }
  return (node.text || "").length;
}

function cmRenderPagerView(root, view, handlers = {}) {
  if (!root) return null;
  root.empty ? root.empty() : (root.textContent = "");
  if (root.replaceChildren) root.replaceChildren();
  else root.children = root.children || [];
  root.className = "bob-cmd-pager-view" + (view.wrap ? " is-wrap" : "");
  root.setAttribute("role", "dialog");
  root.setAttribute("aria-label", "Command output");

  const header = cmPagerEl("header", "bob-cmd-pager-header");
  const pill = cmPagerEl("span", "bob-cmd-pill " + view.status.className, view.status.glyph + " " + view.status.text);
  pill.setAttribute("aria-live", "polite");
  const argv = cmPagerEl("code", "bob-cmd-pager-argv", view.argv);
  argv.setAttribute("title", view.argv);
  const started = cmPagerEl("span", "bob-cmd-pager-started", view.started);
  header.append(pill, argv, started);
  if (view.history && view.history.label) {
    header.appendChild(cmPagerEl("span", "bob-cmd-pager-index", view.history.label));
  }
  if (view.stopVisible) {
    const stop = cmPagerEl("button", "bob-cmd-pager-stop", view.stopConfirm ? "Confirm stop" : "Stop");
    stop.type = "button";
    stop.addEventListener("click", (event) => {
      if (event) {
        event.preventDefault();
        event.stopPropagation();
      }
      if (typeof handlers.onStop === "function") handlers.onStop();
    });
    header.appendChild(stop);
  }
  root.appendChild(header);

  if (view.truncated) {
    const truncated = cmPagerEl("div", "bob-cmd-pager-truncated", "View truncated — open the full log");
    truncated.setAttribute("role", "button");
    truncated.setAttribute("tabindex", "0");
    truncated.addEventListener("click", () => { if (typeof handlers.onOpenLog === "function") handlers.onOpenLog(); });
    root.appendChild(truncated);
  }

  const body = cmPagerEl("div", "bob-cmd-pager-body" + (view.wrap ? " is-wrap" : ""));
  body.setAttribute("tabindex", "0");
  let offset = 0;
  for (const chunk of view.chunks || []) {
    const row = cmPagerEl("div", "bob-cmd-chunk" + (chunk.stream === "err" ? " is-stderr" : ""));
    const nodes = Array.isArray(chunk.nodes) ? chunk.nodes : [{ text: chunk.text || "", style: cmDefaultAnsiStyle() }];
    for (const node of nodes) offset += cmRenderPagerText(row, node, offset, view.search, handlers);
    body.appendChild(row);
  }
  if (!(view.chunks && view.chunks.length)) {
    body.appendChild(cmPagerEl("div", "bob-cmd-chunk is-empty", "No output yet"));
  }
  root.appendChild(body);

  const footer = cmPagerEl("footer", "bob-cmd-pager-footer");
  if (view.search && view.search.mode === "editing") {
    footer.appendChild(cmPagerEl("span", "bob-cmd-pager-search", "/" + view.search.query));
  } else if (view.search && view.search.mode === "idle") {
    const count = view.search.matches.length;
    const current = count && view.search.current >= 0 ? (view.search.current + 1) + "/" + count : "0/" + count;
    footer.appendChild(cmPagerEl("span", "bob-cmd-pager-search", "/" + view.search.query + "  " + current));
  } else if (view.stopConfirm) {
    footer.appendChild(cmPagerEl("span", "bob-cmd-pager-confirm", "Stop this writer? y confirm · esc cancel"));
  } else {
    footer.appendChild(cmPagerEl("span", "bob-cmd-pager-hints", "j k d u g G  / n N  w wrap  y copy  Y argv  r rerun  [ ] history  q close"));
  }
  root.appendChild(footer);
  return { root, header, body, footer };
}

function cmPagerAdvanceSearch(search, dir) {
  const count = search.matches.length;
  if (!count) {
    search.current = -1;
    return search;
  }
  if (search.current < 0) search.current = dir > 0 ? 0 : count - 1;
  else search.current = (search.current + dir + count) % count;
  return search;
}

class CommandModePagerModal extends Modal {
  constructor(app, plugin, options = {}) {
    super(app);
    this.plugin = plugin;
    this.pagerOpen = false;
    this.fromList = Boolean(options.fromList);
    this.runId = String(options.runId || "");
    this.wrap = false;
    this.stopConfirm = false;
    this.search = cmDefaultPagerSearch();
    this.view = null;
    this.nodes = null;
    this.tailTimer = null;
    this.copied = "";
    this.clipboardWrite = typeof options.clipboardWrite === "function" ? options.clipboardWrite : cmPagerWriteClipboard;
  }

  open() {
    if (this.pagerOpen) return this;
    this.pagerOpen = true;
    try {
      return super.open();
    } catch (error) {
      this.pagerOpen = false;
      throw error;
    }
  }

  close() {
    if (!this.pagerOpen) return this;
    this.pagerOpen = false;
    return super.close();
  }

  onOpen() {
    if (this.containerEl && this.containerEl.addClass) this.containerEl.addClass("bob-cmd-pager-host");
    if (this.modalEl && this.modalEl.addClass) this.modalEl.addClass("bob-cmd-pager");
    this.contentEl.empty();
    if (this.contentEl.addClass) this.contentEl.addClass("bob-cmd-pager-content");
    this.viewEl = cmPagerEl("div", "bob-cmd-pager-view");
    this.contentEl.appendChild(this.viewEl);
    if (this.modalEl && this.modalEl.addEventListener) {
      this.modalEl.addEventListener("keydown", (event) => this.handlePagerKeydown(event));
    }
    this.refresh();
    this.startTail();
    if (this.modalEl) {
      this.modalEl.setAttribute("tabindex", "-1");
      if (typeof this.modalEl.focus === "function") this.modalEl.focus();
    }
  }

  onClose() {
    this.stopTail();
    this.pagerOpen = false;
    if (this.plugin && this.plugin.commandModePager === this) this.plugin.commandModePager = null;
    this.contentEl.empty();
  }

  startTail() {
    this.stopTail();
    this.tailTimer = setInterval(() => this.refresh(), CM_TAIL_POLL_MS);
    if (this.tailTimer && typeof this.tailTimer.unref === "function") this.tailTimer.unref();
  }

  stopTail() {
    if (this.tailTimer) {
      try { clearInterval(this.tailTimer); } catch (error) { /* Best effort. */ }
      this.tailTimer = null;
    }
  }

  showRun(runId) {
    this.runId = String(runId || "");
    this.stopConfirm = false;
    this.search = cmDefaultPagerSearch();
    this.refresh();
  }

  payload() {
    return cmPagerLoadPayload(this.plugin && this.plugin.commandModeRunner, this.runId);
  }

  records() {
    const runner = this.plugin && this.plugin.commandModeRunner;
    if (!runner) return [];
    try { return cmListRecords(runner.fs(), runner.runsDir()); }
    catch (error) { return []; }
  }

  refresh() {
    const payload = this.payload();
    if (!payload) {
      if (this.viewEl) {
        this.viewEl.empty ? this.viewEl.empty() : (this.viewEl.textContent = "Run not found");
      }
      return null;
    }
    const runner = this.plugin.commandModeRunner;
    const vaultBase = runner && typeof runner.deps.vaultBase === "function" ? runner.deps.vaultBase() : cmVaultBasePath(this.app);
    const previous = this.nodes && this.nodes.body;
    const wasAtBottom = previous
      ? (Number(previous.scrollTop) || 0) + (Number(previous.clientHeight) || 0) >= (Number(previous.scrollHeight) || 0) - 8
      : true;
    const savedTop = previous ? Number(previous.scrollTop) || 0 : 0;
    this.view = cmBuildPagerView(payload, {
      app: this.app,
      vaultBase,
      records: this.records(),
      search: this.search,
      wrap: this.wrap,
      stopConfirm: this.stopConfirm,
      queuedBehind: cmPagerQueuedBehind(runner),
      nowMs: Date.now(),
    });
    this.nodes = cmRenderPagerView(this.viewEl, this.view, {
      onStop: () => this.requestStop(),
      onOpenLog: () => this.openFullLog(),
      onLink: (link) => this.openLink(link),
    });
    if (this.nodes && this.nodes.body) {
      const body = this.nodes.body;
      body.scrollTop = wasAtBottom ? (body.scrollHeight || 0) : savedTop;
    }
    return this.view;
  }

  openFullLog() {
    const runner = this.plugin && this.plugin.commandModeRunner;
    if (!runner || typeof this.plugin.commandModeOpenPath !== "function") return { ok: false };
    const paths = cmRunFilePaths(runner.runsDir(), this.runId, runner.pathModule());
    return this.plugin.commandModeOpenPath(paths.out);
  }

  openLink(link) {
    const workspace = this.app && this.app.workspace;
    if (!workspace || typeof workspace.openLinkText !== "function") return { ok: false, reason: "note opener unavailable" };
    const target = link.href || link.path;
    const eState = {};
    if (typeof link.line === "number") eState.line = Math.max(0, link.line - 1);
    try {
      const opened = workspace.openLinkText(target, "", Boolean(link.newLeaf), { eState });
      if (!link.newLeaf) this.close();
      return opened && typeof opened.then === "function" ? opened.then(() => ({ ok: true })) : { ok: true };
    } catch (error) {
      return { ok: false, reason: String((error && error.message) || error) };
    }
  }

  requestStop() {
    const record = this.view && this.view.record;
    if (!record || record.outcome !== "running") return { ok: false, reason: "run is not active" };
    if (record.effect !== "reads" && !this.stopConfirm) {
      this.stopConfirm = true;
      this.refresh();
      return { ok: true, confirm: true };
    }
    this.stopConfirm = false;
    const runner = this.plugin && this.plugin.commandModeRunner;
    if (!runner || typeof runner.stop !== "function") return { ok: false, reason: "run is not active" };
    const result = runner.stop(this.runId);
    this.refresh();
    return result;
  }

  backToList() {
    if (typeof this.onBackToList === "function") {
      this.onBackToList();
      return;
    }
    this.close();
  }

  handlePagerKeydown(event) {
    const action = cmHandlePagerKey(event, {
      search: this.search,
      stopConfirm: this.stopConfirm,
      hasSelection: cmPagerHasSelection(),
    });
    if (!action || action.type === "none") return false;
    if (event && typeof event.preventDefault === "function") event.preventDefault();
    if (event && typeof event.stopPropagation === "function") event.stopPropagation();
    this.applyPagerAction(action);
    return true;
  }

  applyPagerAction(action) {
    const body = this.nodes && this.nodes.body;
    switch (action.type) {
      case "scroll": {
        if (!body) return;
        body.scrollTop = cmPagerApplyScroll({
          top: Number(body.scrollTop) || 0,
          view: Number(body.clientHeight) || 0,
          height: Number(body.scrollHeight) || 0,
        }, action);
        return;
      }
      case "wrap":
        this.wrap = !this.wrap;
        this.refresh();
        return;
      case "copy-output":
        void this.clipboardWrite(cmPagerCopyOutput(this.view && this.view.chunks)).then((result) => {
          if (result && result.ok) this.copied = "output";
        });
        return;
      case "copy-command":
        void this.clipboardWrite(cmPagerCopyCommand(this.view && this.view.record)).then((result) => {
          if (result && result.ok) this.copied = "command";
        });
        return;
      case "rerun":
        if (this.plugin && typeof this.plugin.commandModeRerun === "function") {
          void Promise.resolve(this.plugin.commandModeRerun(this.view && this.view.record)).then((result) => {
            if (result && result.runId) this.showRun(result.runId);
          });
        }
        return;
      case "history": {
        const history = this.view && this.view.history;
        const nextId = action.dir > 0 ? history && history.olderId : history && history.newerId;
        if (nextId) this.showRun(nextId);
        return;
      }
      case "stop-request":
        this.requestStop();
        return;
      case "stop":
        this.stopConfirm = true;
        this.requestStop();
        return;
      case "stop-cancel":
        this.stopConfirm = false;
        this.refresh();
        return;
      case "search-start":
        this.search = { ...cmDefaultPagerSearch(), mode: "editing" };
        this.refresh();
        return;
      case "search-type":
        this.search.query = String(this.search.query || "") + action.char;
        this.refresh();
        return;
      case "search-backspace":
        this.search.query = String(this.search.query || "").slice(0, -1);
        this.refresh();
        return;
      case "search-commit":
        if (!this.search.query) {
          this.search = cmDefaultPagerSearch();
        } else {
          this.search.mode = "idle";
          this.search.matches = cmFindSearchMatches(this.view && this.view.visible, this.search.query);
          this.search.current = this.search.matches.length ? 0 : -1;
        }
        this.refresh();
        return;
      case "search-cancel":
        this.search = cmDefaultPagerSearch();
        this.refresh();
        return;
      case "search-next":
        cmPagerAdvanceSearch(this.search, 1);
        this.refresh();
        return;
      case "search-prev":
        cmPagerAdvanceSearch(this.search, -1);
        this.refresh();
        return;
      case "back":
        this.backToList();
        return;
      case "escape":
        if (this.fromList) this.backToList();
        else this.close();
        return;
      case "close":
        this.close();
        return;
      default:
        return;
    }
  }
}
// ---- src/160-sheet-rank.js ----
// Bob Command Mode: bottom sheet row model, fuzzy ranking, and frecency.
// Pure: no DOM and no Obsidian imports. The sheet modal (170) renders rows,
// and node tests require this file through the built main.js helpers.

const CM_SHEET_RECENT_LIMIT = 4;
const CM_SHEET_FRECENCY_WINDOW = 10;
// Shown only when the median tops two seconds.
const CM_SHEET_DURATION_FLOOR_MS = 2000;
// [max age in days, weight] per the sheet spec: runs at most 4 / 14 / 31 /
// 90 days old earn 100 / 70 / 50 / 30, older runs earn 10.
const CM_SHEET_FRECENCY_BUCKETS = [
  [4, 100],
  [14, 70],
  [31, 50],
  [90, 30],
  [Infinity, 10],
];
const CM_SHEET_FIELD_WEIGHTS = { path: 1.0, alias: 0.9, title: 0.8, keywords: 0.6 };
const CM_SHEET_PATH_PREFIX_BONUS = 8;
const CM_SHEET_KEYWORD_BONUS = 8;

// Row-kind icons (Lucide names). Entries derive their kind from effect and
// network; the modal falls back to a text glyph when setIcon is unavailable.
const CM_SHEET_ICONS = {
  network: "globe",
  syncs: "refresh-cw",
  writes: "pencil-line",
  reads: "book-open",
  surface: "app-window",
  vim: "terminal-square",
  help: "help-circle",
  recent: "history",
  plain: "command",
};
const CM_SHEET_ICON_FALLBACK = {
  network: "◉",
  syncs: "⟳",
  writes: "✎",
  reads: "ⓘ",
  surface: "▤",
  vim: "›",
  help: "?",
  recent: "↺",
  plain: "⌘",
};

// Surface rows owned by the plugin. Each runs an existing Obsidian command and
// is feature-detected through app.commands.commands[id]; a missing command
// makes the row unavailable. There is no "Preview article adoption" row: the
// plan names a bob-articles adopt-preview command id, but no such command
// exists in bob-articles' source (only format-article and convert-to-article),
// so there is nothing to detect.
const CM_SHEET_SURFACE_ROWS = [
  { plugin: "bob-ledger-tools", id: "open-today-daily-note", title: "Today's daily note", section: "daily" },
  { plugin: "bob-navigation-hotkeys", id: "open-pomodoro-themes-manager", title: "Pomodoro themes manager", section: "daily" },
  { plugin: "bob-ledger-tools", id: "open-stats", title: "Stats dashboard", section: "daily" },
  { plugin: "bob-navigation-hotkeys", id: "open-dash-tasks", title: "Dash tasks", section: "tasks" },
  { plugin: "bob-navigation-hotkeys", id: "open-relation-labels-manager", title: "Relation labels manager", section: "tasks" },
  { plugin: "bob-ledger-tools", id: "open-reading-board", title: "Reading Board", section: "vault" },
  { plugin: "bob-articles", id: "format-article", title: "Format this article", section: "vault" },
];

function cmSheetLower(value) {
  return String(value || "").toLowerCase();
}

function cmSheetWords(text) {
  return cmSheetLower(text).split(/[\s_\/-]+/).filter(Boolean);
}

// Subsequence match of token inside field. Scores consecutive runs and word
// starts; returns 0 when token is not a subsequence of field.
function cmFuzzyFieldScore(token, field) {
  const needle = cmSheetLower(token);
  const hay = cmSheetLower(field);
  if (!needle || !hay) return 0;
  if (hay === needle) return 14;
  if (hay.startsWith(needle)) return 10;
  let score = 0;
  let ni = 0;
  let run = 0;
  for (let hi = 0; hi < hay.length && ni < needle.length; hi += 1) {
    if (hay[hi] === needle[ni]) {
      ni += 1;
      run += 1;
      score += 1 + run;
      if (hi === 0 || /[\s_\/\-:.]/.test(hay[hi - 1])) score += 2;
    } else {
      run = 0;
    }
  }
  if (ni < needle.length) return 0;
  const words = cmSheetWords(hay);
  if (words.some((word) => word.startsWith(needle))) score += 4;
  return score;
}

function cmSheetTokenize(query) {
  return String(query || "").toLowerCase().split(/\s+/).filter(Boolean);
}

// Best weighted field score for one token across the row's match views.
// Views: {path, alias, title, keywords} as plain strings.
function cmSheetTokenScore(token, views) {
  let best = 0;
  for (const field of Object.keys(CM_SHEET_FIELD_WEIGHTS)) {
    const text = views && views[field];
    if (!text) continue;
    const score = cmFuzzyFieldScore(token, text) * CM_SHEET_FIELD_WEIGHTS[field];
    if (score > best) best = score;
  }
  return best;
}

// Ranked score for a row. Every query token must match somewhere (AND);
// exact path-prefix and exact keyword hits add a bonus. Returns -1 when the
// row does not match.
function cmRankSheetRow(queryText, views, keywords) {
  const tokens = cmSheetTokenize(queryText);
  if (!tokens.length) return 0;
  let total = 0;
  for (const token of tokens) {
    const tokenScore = cmSheetTokenScore(token, views);
    if (tokenScore <= 0) return -1;
    total += tokenScore;
  }
  const query = cmSheetLower(queryText).trim().replace(/\s+/g, " ");
  if (views && cmSheetLower(views.path).startsWith(query)) total += CM_SHEET_PATH_PREFIX_BONUS;
  const words = Array.isArray(keywords) ? keywords.map(cmSheetLower) : [];
  if (tokens.some((token) => words.includes(token))) total += CM_SHEET_KEYWORD_BONUS;
  return total;
}

function cmSheetRowViews(row) {
  return {
    path: Array.isArray(row.path) ? row.path.join(" ") : String(row.path || ""),
    alias: Array.isArray(row.aliases) ? row.aliases.join(" ") : String(row.aliases || ""),
    title: String(row.title || ""),
    keywords: Array.isArray(row.keywords) ? row.keywords.join(" ") : String(row.keywords || ""),
  };
}

// Rank rows for a query: best match first. Frecency breaks ties, then the
// input (catalog) order. Never mutates the input.
function cmRankSheetRows(query, rows, frecencyByKey) {
  const scored = [];
  for (let index = 0; index < (rows || []).length; index += 1) {
    const row = rows[index];
    const views = cmSheetRowViews(row);
    const score = cmRankSheetRow(query, views, row.keywords);
    if (score < 0) continue;
    scored.push({ row, score, index });
  }
  scored.sort((left, right) => {
    if (right.score !== left.score) return right.score - left.score;
    const leftFrec = Number((frecencyByKey && frecencyByKey[left.row.key]) || 0);
    const rightFrec = Number((frecencyByKey && frecencyByKey[right.row.key]) || 0);
    if (rightFrec !== leftFrec) return rightFrec - leftFrec;
    return left.index - right.index;
  });
  return scored.map((item) => item.row);
}

function cmSheetRunTimeMs(run) {
  const stamp = (run && (run.finished_at || run.started_at)) || null;
  const ms = stamp ? Date.parse(stamp) : NaN;
  return Number.isFinite(ms) ? ms : null;
}

function cmSheetFrecencyWeight(ageMs) {
  const days = ageMs / 86400000;
  for (const [maxDays, weight] of CM_SHEET_FRECENCY_BUCKETS) {
    if (days <= maxDays) return weight;
  }
  return 10;
}

// Frecency per row key over that row's last 10 runs. Counts runs from this
// host plus runs recorded before hosts were tracked (null host).
function cmSheetFrecency(runs, key, nowMs, host) {
  const now = typeof nowMs === "number" ? nowMs : Date.now();
  let total = 0;
  let seen = 0;
  const ordered = [...(runs || [])].reverse();
  for (const run of ordered) {
    if (seen >= CM_SHEET_FRECENCY_WINDOW) break;
    if (!run || cmSheetRunKey(run) !== key) continue;
    if (run.host && host && run.host !== host) continue;
    const at = cmSheetRunTimeMs(run);
    if (at === null || at > now) continue;
    total += cmSheetFrecencyWeight(now - at);
    seen += 1;
  }
  return total;
}

function cmSheetFrecencyMap(runs, rows, nowMs, host) {
  const map = {};
  for (const row of rows || []) {
    if (!row || !row.key || row.key in map) continue;
    map[row.key] = cmSheetFrecency(runs, row.key, nowMs, host);
  }
  return map;
}

function cmSheetRunKey(run) {
  if (run && run.entry_id) return "entry:" + run.entry_id;
  return "argv:" + JSON.stringify((run && run.argv) || []);
}

function cmSheetAgeText(ms) {
  const age = Math.max(0, Number(ms) || 0);
  const minutes = Math.floor(age / 60000);
  if (minutes < 1) return "now";
  if (minutes < 60) return minutes + "m";
  const hours = Math.floor(minutes / 60);
  if (hours < 48) return hours + "h";
  return Math.floor(hours / 24) + "d";
}

const CM_SHEET_OUTCOME_GLYPH = { completed: "✓", attention: "◐", failed: "✗", unknown: "?", stopped: "■", running: "⟳" };

// Last four distinct argv, newest first, each with outcome glyph, age, and
// duration for the RECENT section.
function cmSheetRecentRows(runs, nowMs) {
  const now = typeof nowMs === "number" ? nowMs : Date.now();
  const seen = new Set();
  const rows = [];
  for (const run of [...(runs || [])].reverse()) {
    if (rows.length >= CM_SHEET_RECENT_LIMIT) break;
    if (!run || !Array.isArray(run.argv)) continue;
    const signature = JSON.stringify(run.argv);
    if (seen.has(signature)) continue;
    seen.add(signature);
    const at = cmSheetRunTimeMs(run);
    rows.push({
      key: run.entry_id ? "entry:" + run.entry_id : "argv:" + signature,
      kind: "recent",
      path: run.argv[0] === "bob" ? run.argv.slice(1) : [...run.argv],
      title: run.title || run.entry_id || "Last command",
      about: run.summary || "",
      argv: [...run.argv],
      entryId: run.entry_id || null,
      presentation: run.presentation || "action",
      policy: "run",
      outcome: run.outcome || "unknown",
      glyph: CM_SHEET_OUTCOME_GLYPH[run.outcome] || "?",
      age: at === null ? "" : cmSheetAgeText(now - at),
      duration: typeof run.duration_ms === "number" ? run.duration_ms : null,
      icon: "recent",
    });
  }
  return rows;
}

// Median of the row's last 10 local durations; null when under the floor.
function cmSheetMedianDuration(runs, row, host) {
  const signature = row.kind === "recent" && row.argv
    ? "argv:" + JSON.stringify(row.argv)
    : row.key;
  const durations = [];
  for (const run of [...(runs || [])].reverse()) {
    if (durations.length >= CM_SHEET_FRECENCY_WINDOW) break;
    if (!run || typeof run.duration_ms !== "number") continue;
    if (run.host && host && run.host !== host) continue;
    const key = run.entry_id && row.entryId
      ? (run.entry_id === row.entryId ? signature : null)
      : (cmSheetRunKey(run) === signature ? signature : null);
    if (key) durations.push(run.duration_ms);
  }
  if (!durations.length) return null;
  durations.sort((a, b) => a - b);
  const median = durations[Math.floor(durations.length / 2)];
  return median > CM_SHEET_DURATION_FLOOR_MS ? median : null;
}

function cmSheetEntryKind(entry) {
  if (entry && entry.network) return "network";
  const effect = cmNormalizeEffect(entry && entry.effect);
  if (effect === "syncs") return "syncs";
  if (effect === "writes") return "writes";
  return "reads";
}

// Alias strings whose `to` path names this entry, e.g. "ref clip".
function cmSheetEntryAliases(catalog, entry) {
  const path = Array.isArray(entry && entry.path) ? entry.path : [];
  const found = [];
  for (const alias of ((catalog && catalog.aliases) || [])) {
    if (alias && Array.isArray(alias.to) && Array.isArray(alias.from) &&
        alias.to.length === path.length && alias.to.every((word, i) => word === path[i])) {
      found.push(alias.from.join(" "));
    }
  }
  return found;
}

function cmSheetEntryUnavailable(entry, host) {
  const hosts = Array.isArray(entry && entry.hosts) ? entry.hosts.filter(Boolean) : [];
  if (hosts.length && (!host || !hosts.includes(host))) return "Unavailable here";
  return null;
}

// Catalog entry rows in catalog order. Skips entries retired by an exclusion
// rule that names the entry's exact path (for example bare `capture`, whose
// free-text runs stay refused); named rows under an excluded prefix keep
// their row because the runner runs them by entry id.
function cmSheetEntryRows(catalog, host) {
  const entries = (catalog && Array.isArray(catalog.entries) && catalog.entries) || [];
  const excludedPaths = new Set(
    ((catalog && Array.isArray(catalog.excluded) && catalog.excluded) || [])
      .filter((rule) => rule && Array.isArray(rule.path))
      .map((rule) => JSON.stringify(rule.path)),
  );
  const rows = [];
  for (const entry of entries) {
    if (!entry || !Array.isArray(entry.path) || !entry.path.length) continue;
    if (excludedPaths.has(JSON.stringify(entry.path)) && !(entry.fixed || []).length) continue;
    const unavailable = cmSheetEntryUnavailable(entry, host);
    rows.push({
      key: "entry:" + entry.id,
      kind: "entry",
      subkind: cmSheetEntryKind(entry),
      icon: cmSheetEntryKind(entry),
      path: [...entry.path, ...((entry.fixed || []).map(String))],
      basePath: [...entry.path],
      fixed: (entry.fixed || []).map(String),
      aliases: cmSheetEntryAliases(catalog, entry),
      title: entry.title || entry.id,
      about: (entry.about || "").split("\n")[0],
      keywords: Array.isArray(entry.keywords) ? [...entry.keywords] : [],
      effect: cmNormalizeEffect(entry.effect),
      presentation: cmNormalizePresentation(entry.presentation),
      policy: cmNormalizePolicy(entry.policy),
      hasPreview: Array.isArray(entry.preview) && entry.preview.length > 0,
      confirm: entry.policy === "confirm" ? String(entry.confirm || "") : null,
      required: cmRequiredPositionals(entry),
      entryId: entry.id,
      section: entry.section || "daily",
      unavailable,
    });
  }
  return rows;
}

function cmSheetSurfaceRows(surfaceAvailable) {
  return CM_SHEET_SURFACE_ROWS.map((item) => {
    const commandId = item.plugin + ":" + item.id;
    const available = typeof surfaceAvailable === "function" ? surfaceAvailable(commandId) : true;
    return {
      key: "surface:" + commandId,
      kind: "surface",
      icon: "surface",
      path: [item.title],
      title: item.title,
      about: "Open in Obsidian",
      keywords: [item.id.replace(/-/g, " ")],
      effect: "opens",
      presentation: "surface",
      policy: "run",
      hasPreview: false,
      required: [],
      surfaceId: commandId,
      section: item.section,
      unavailable: available ? null : "Enable " + item.plugin,
    };
  });
}

function cmSheetPlainRows() {
  return [
    {
      key: "plain:bob-help", kind: "plain", icon: "help", path: ["bob", "--help"],
      title: "bob help", about: "Every command, in the pager", keywords: ["help", "usage", "man"],
      effect: "reads", presentation: "report", policy: "run", hasPreview: false,
      required: [], argv: ["--help"], section: "setup", unavailable: null,
    },
    {
      key: "plain:show-last-output", kind: "plain", icon: "plain", path: ["Show last output"],
      title: "Show last output", about: "The newest run, in the pager", keywords: ["last", "output", "history"],
      effect: "reads", presentation: "report", policy: "run", hasPreview: false,
      required: [], action: "show-last-output", section: "setup", unavailable: null,
    },
    {
      key: "plain:run-history", kind: "plain", icon: "recent", path: ["Run history"],
      title: "Run history", about: "Every recorded run, newest first", keywords: ["history", "runs", "log"],
      effect: "reads", presentation: "report", policy: "run", hasPreview: false,
      required: [], action: "run-history", section: "setup", unavailable: null,
    },
  ];
}

function cmSheetIsHttpUrl(value) {
  return /^https?:\/\/\S+$/i.test(String(value || "").trim());
}

// Normalize a note's frontmatter `type` plus the article check into the
// context kind the sheet builds "For this note" rows from.
function cmSheetNoteKind(frontmatterType, isArticle) {
  const values = Array.isArray(frontmatterType) ? frontmatterType : [frontmatterType];
  const normalized = values
    .map((value) => String(value || "").trim().replace(/^\[\[/, "").replace(/\]\]$/, "").trim().toLowerCase())
    .filter(Boolean);
  if (normalized.includes("ref")) return "ref";
  if (normalized.includes("area")) return "area";
  if (normalized.includes("project")) return "project";
  if (isArticle || normalized.includes("article")) return "article";
  return "note";
}

// Context-filled argv rows: complete argv (never auto-filled on a plain row
// run), each naming the entry it fills. Only rows whose entry exists in the
// catalog are returned.
function cmSheetContextRows(catalog, context) {
  const byId = new Map();
  for (const entry of ((catalog && catalog.entries) || [])) {
    if (entry && entry.id) byId.set(entry.id, entry);
  }
  const rows = [];
  const fill = (entryId, userArgs, tagline) => {
    const entry = byId.get(entryId);
    if (!entry) return;
    rows.push({
      key: "ctx:" + entryId + ":" + JSON.stringify(userArgs),
      kind: "entry",
      context: true,
      subkind: cmSheetEntryKind(entry),
      icon: cmSheetEntryKind(entry),
      path: [...entry.path],
      basePath: [...entry.path],
      fixed: (entry.fixed || []).map(String),
      aliases: [],
      title: entry.title || entryId,
      about: tagline || (entry.about || "").split("\n")[0],
      tagline: tagline || null,
      keywords: Array.isArray(entry.keywords) ? [...entry.keywords] : [],
      effect: cmNormalizeEffect(entry.effect),
      presentation: cmNormalizePresentation(entry.presentation),
      policy: cmNormalizePolicy(entry.policy),
      hasPreview: Array.isArray(entry.preview) && entry.preview.length > 0,
      confirm: entry.policy === "confirm" ? String(entry.confirm || "") : null,
      required: cmRequiredPositionals(entry),
      entryId,
      userArgs: [...userArgs],
      section: "context",
      unavailable: null,
    });
  };
  const note = context && context.notePath;
  const kind = (context && context.noteKind) || null;
  if (note) {
    if (kind === "ref") {
      fill("ref-today", [note], "Pull into today's Pomodoro");
      fill("ref-show", [note], "Show this reference");
      fill("ref-rename", [note], "Rename this reference");
    } else if (kind === "area" || kind === "project") {
      fill("ready", [note], "Ready lane for this note");
    } else if (kind === "article") {
      fill("articles-outline", [note], "Outline this article");
    }
    fill("ref-create", [note], "Snapshot note to Highlights");
  }
  const url = context && context.clipboardUrl;
  if (url && cmSheetIsHttpUrl(url)) {
    fill("ref-queue", [url], "Queue link for reading");
    fill("ref-create", [url], "Create reference now");
    fill("ref-find", [url], "Is this in my library?");
  }
  return rows;
}

// Every row the sheet can show, in catalog order: entries, then surface rows,
// then the three plain rows. Context rows are separate (they head the empty
// query) but join the ranked pool once the user types.
function cmBuildSheetRows(catalog, options = {}) {
  const host = options.host || null;
  const rows = [
    ...cmSheetEntryRows(catalog, host),
    ...cmSheetSurfaceRows(options.surfaceAvailable),
    ...cmSheetPlainRows(),
  ];
  if (options.context) rows.push(...cmSheetContextRows(catalog, options.context));
  return rows;
}

// Empty-query sections in sheet order: RECENT, FOR THIS NOTE, FROM CLIPBOARD,
// then one per catalog section in catalog order.
function cmGroupSheetRows(rows, catalog, context) {
  const groups = [];
  const recent = (rows || []).filter((row) => row && row.kind === "recent");
  if (recent.length) groups.push({ id: "recent", title: "RECENT", rows: recent });
  const noteRows = (rows || []).filter((row) => row && row.context && row.section === "context" && row.userArgs &&
    !(context && context.clipboardUrl && row.userArgs.includes(context.clipboardUrl)));
  if (noteRows.length) {
    const label = context && context.notePath ? "FOR THIS NOTE · " + context.notePath : "FOR THIS NOTE";
    groups.push({ id: "context", title: label, rows: noteRows });
  }
  const clipRows = (rows || []).filter((row) => row && row.context && !noteRows.includes(row));
  if (clipRows.length) {
    const label = context && context.clipboardUrl ? "FROM CLIPBOARD · " + context.clipboardUrl : "FROM CLIPBOARD";
    groups.push({ id: "clipboard", title: label, rows: clipRows });
  }
  const rest = (rows || []).filter((row) => row && row.kind !== "recent" && !row.context);
  const sections = (catalog && Array.isArray(catalog.sections) && catalog.sections) || [];
  const seen = new Set();
  for (const section of sections) {
    if (!section || !section.id) continue;
    seen.add(section.id);
    const sectionRows = rest.filter((row) => (row.section || "daily") === section.id);
    if (sectionRows.length) groups.push({ id: section.id, title: String(section.title || section.id).toUpperCase(), rows: sectionRows });
  }
  const homeless = rest.filter((row) => !seen.has(row.section || "daily"));
  if (homeless.length) groups.push({ id: "more", title: "MORE", rows: homeless });
  return groups;
}

// Footer hint bar per stage.
function cmSheetFooterHints(stage) {
  if (stage === "confirm") return "⌃↵ run · esc back";
  if (stage === "output") return "r rerun · y copy · [ ] history · : list · esc back · q close";
  return "↵ run · ⇥ args · ⇧↵ preview · ⌃↵ run now · ? help · :: vim · esc close";
}

// List-stage key intent. `args` and `vim` stages belong to the args-vim phase;
// this maps only what the sheet owns and reports `unhandled` for the rest.
function cmSheetListAction(event, state = {}) {
  if (!event || typeof event.key !== "string") return { type: "none" };
  const key = event.key;
  const ctrl = Boolean(event.ctrlKey);
  const shift = Boolean(event.shiftKey);
  const meta = Boolean(event.metaKey);
  if (meta) return { type: "none" };
  if (key === "Escape") return { type: "close" };
  if (key === "Enter" && ctrl && !shift) return { type: "run-now" };
  if (key === "Enter" && shift && !ctrl) return { type: "preview" };
  if (key === "Enter" && !ctrl && !shift) return { type: "run" };
  if (key === "Tab" && !ctrl) return { type: "args" };
  if ((key === "ArrowDown" || (ctrl && key === "n")) && !shift) return { type: "down" };
  if ((key === "ArrowUp" || (ctrl && key === "p")) && !shift) return { type: "up" };
  if (key === "?" && !ctrl && String((state.query || "")).endsWith("?")) return { type: "help" };
  if (key === "Backspace" && !ctrl && !String(state.query || "").length) return { type: "close" };
  return { type: "none" };
}

// Help argv for a `?` run: `bob <path> --help` for the selected row, or bare
// `bob --help` with no selection.
function cmSheetHelpArgv(selectedRow) {
  if (selectedRow && Array.isArray(selectedRow.basePath) && selectedRow.basePath.length) {
    return [...selectedRow.basePath, "--help"];
  }
  return ["--help"];
}
// ---- src/170-sheet.js ----
// Bob Command Mode: the `Bob: Command mode` bottom sheet. Lists catalog,
// surface, context, and recent rows with fuzzy ranking; runs them through the
// runner with preview-first and confirm flows; grows in place into the output
// pager for reports, previews, and `?` help. Argument mode, typed runs, and
// Vim routing belong to the args-vim phase, which extends this modal.

function cmSheetSetIcon(el, name, fallback) {
  try {
    const obsidian = require("obsidian");
    if (obsidian && typeof obsidian.setIcon === "function") {
      obsidian.setIcon(el, name);
      return;
    }
  } catch (error) {
    // Headless tests and older shims fall through to the glyph.
  }
  el.textContent = String(fallback);
}

// Same rule as bob-articles' articleHasArticleType (020-article-core.js):
// the frontmatter type names "article", alone or in a list.
function cmSheetArticleType(type) {
  const values = Array.isArray(type) ? type : [type];
  return values.some((value) => String(value || "").trim()
    .replace(/^\[\[/, "").replace(/\]\]$/, "").trim().toLowerCase() === "article");
}

function cmSheetCaptureContext(app) {
  const context = { notePath: null, noteKind: null, clipboardUrl: null };
  try {
    const workspace = app && app.workspace;
    const view = workspace && typeof workspace.getActiveViewOfType === "function"
      ? workspace.getActiveViewOfType(MarkdownView)
      : null;
    const file = view && view.file;
    if (file && file.path) {
      context.notePath = file.path;
      let frontmatter = null;
      try {
        const cache = app.metadataCache && typeof app.metadataCache.getFileCache === "function"
          ? app.metadataCache.getFileCache(file)
          : null;
        frontmatter = (cache && cache.frontmatter) || null;
      } catch (error) {
        frontmatter = null;
      }
      context.noteKind = cmSheetNoteKind(frontmatter && frontmatter.type, cmSheetArticleType(frontmatter && frontmatter.type));
    }
  } catch (error) {
    // No active note: the sheet still opens with catalog rows.
  }
  return context;
}

function cmSheetReadClipboard() {
  try {
    const clipboard = typeof navigator !== "undefined" && navigator.clipboard;
    if (!clipboard || typeof clipboard.readText !== "function") return Promise.resolve(null);
    return clipboard.readText().then((text) => {
      const url = String(text || "").trim().split(/\s+/)[0] || "";
      return cmSheetIsHttpUrl(url) ? url : null;
    }).catch(() => null);
  } catch (error) {
    return Promise.resolve(null);
  }
}

function cmSheetRowArgv(row) {
  if (row && Array.isArray(row.argv)) return [...row.argv];
  const base = (row && Array.isArray(row.basePath) && row.basePath) ||
    (Array.isArray(row.path) && row.path) || [];
  const userArgs = (row && Array.isArray(row.userArgs) && row.userArgs) || [];
  return [...base, ...userArgs];
}

function cmSheetMissingPositional(row) {
  const required = (row && Array.isArray(row.required) && row.required) || [];
  const userArgs = (row && Array.isArray(row.userArgs) && row.userArgs) || [];
  const filled = userArgs.length;
  const missing = required[filled];
  return missing ? String(missing.name || missing.slot || "value") : null;
}

class CommandModeSheetModal extends Modal {
  constructor(app, plugin, options = {}) {
    super(app);
    this.plugin = plugin;
    this.sheetOpen = false;
    this.stage = "list";
    this.query = String((options && options.initialQuery) || "");
    this.catalog = (plugin && plugin.commandModeCatalog) || null;
    this.host = (plugin && plugin.commandModeRunner && plugin.commandModeRunner.host) || null;
    this.context = (options && options.context) || cmSheetCaptureContext(app);
    this.rows = [];
    this.visible = [];
    this.groups = [];
    this.selectedKey = null;
    this.runRecords = [];
    this.frecency = {};
    this.confirmRow = null;
    this.previewRunId = null;
    this.previewResult = null;
    this.previewCarry = [];
    this.outputRunId = null;
    this.outputTitle = "";
    this.outputWrap = false;
    this.outputStopConfirm = false;
    this.outputSearch = cmDefaultPagerSearch();
    this.outputView = null;
    this.outputNodes = null;
    this.tailTimer = null;
    this.hint = null;
    this.surfaceAvailable = (options && options.surfaceAvailable) || null;
    this.onPickVim = (options && options.onPickVim) || null;
  }

  open() {
    if (this.sheetOpen) return this;
    this.sheetOpen = true;
    try {
      return super.open();
    } catch (error) {
      this.sheetOpen = false;
      throw error;
    }
  }

  close() {
    if (!this.sheetOpen) return this;
    this.sheetOpen = false;
    return super.close();
  }

  onOpen() {
    if (this.containerEl && this.containerEl.addClass) this.containerEl.addClass("bob-cmd-sheet-host");
    if (this.modalEl && this.modalEl.addClass) this.modalEl.addClass("bob-cmd-sheet");
    this.refreshRecords();
    this.rebuildRows();
    this.render();
    if (this.modalEl && this.modalEl.addEventListener) {
      this.modalEl.addEventListener("keydown", (event) => this.handleSheetKeydown(event));
    }
    void cmSheetReadClipboard().then((url) => {
      if (!this.sheetOpen || !url || this.context.clipboardUrl === url) return;
      this.context = { ...this.context, clipboardUrl: url };
      const keep = this.selectedKey;
      this.rebuildRows();
      this.selectedKey = keep;
      if (this.stage === "list") this.render();
    });
  }

  onClose() {
    this.stopTail();
    this.sheetOpen = false;
    if (this.plugin && this.plugin.commandModeSheet === this) this.plugin.commandModeSheet = null;
  }

  runner() {
    return this.plugin && this.plugin.commandModeRunner;
  }

  refreshRecords() {
    const runner = this.runner();
    try {
      this.runRecords = runner ? cmListRecords(runner.fs(), runner.runsDir()) : [];
    } catch (error) {
      this.runRecords = [];
    }
  }

  rebuildRows() {
    const surfaceAvailable = this.surfaceAvailable || ((id) => {
      try {
        const commands = this.app && this.app.commands && this.app.commands.commands;
        return Boolean(commands && commands[id]);
      } catch (error) {
        return false;
      }
    });
    const contextRows = cmSheetContextRows(this.catalog, this.context);
    this.rows = [
      ...cmSheetEntryRows(this.catalog, this.host),
      ...cmSheetSurfaceRows(surfaceAvailable),
      ...cmSheetPlainRows(),
      ...contextRows,
    ];
    if (!this.query.trim()) {
      this.refreshRecords();
      this.rows = [...cmSheetRecentRows(this.runRecords, Date.now()), ...this.rows];
    }
    this.frecency = cmSheetFrecencyMap(this.runRecords, this.rows, Date.now(), this.host);
    this.recomputeVisible();
  }

  recomputeVisible() {
    const query = this.query.trim();
    if (!query) {
      this.groups = cmGroupSheetRows(this.rows, this.catalog, this.context);
      this.visible = this.groups.flatMap((group) => group.rows);
    } else {
      this.groups = [];
      this.visible = cmRankSheetRows(query.replace(/\?$/, ""), this.rows, this.frecency);
    }
    if (!this.visible.some((row) => row && row.key === this.selectedKey)) {
      this.selectedKey = this.visible.length ? this.visible[0].key : null;
    }
  }

  selectedRow() {
    return this.visible.find((row) => row && row.key === this.selectedKey) || null;
  }

  select(delta) {
    if (!this.visible.length) return;
    let index = this.visible.findIndex((row) => row && row.key === this.selectedKey);
    index = index < 0 ? 0 : (index + delta + this.visible.length) % this.visible.length;
    this.selectedKey = this.visible[index].key;
    this.render();
    this.scrollSelectionIntoView();
  }

  scrollSelectionIntoView() {
    // Best effort; headless stubs ignore it.
  }

  render() {
    if (!this.sheetOpen && !this.contentEl) return;
    this.contentEl.empty();
    if (this.contentEl.addClass) this.contentEl.addClass("bob-cmd-sheet-content");
    this.renderHeader();
    if (this.stage === "confirm") this.renderConfirm();
    else if (this.stage === "output") this.renderOutput();
    else this.renderList();
    this.renderFooter();
  }

  renderHeader() {
    const header = this.contentEl.createEl("div", { cls: "bob-cmd-sheet-header" });
    header.createEl("span", { cls: "bob-cmd-sheet-brand", text: "bob" });
    const version = this.catalog && this.catalog.bob_version ? "bob " + this.catalog.bob_version : "";
    header.createEl("span", {
      cls: "bob-cmd-sheet-host",
      text: [this.host, version].filter(Boolean).join(" · "),
    });
    const inputWrap = this.contentEl.createEl("div", { cls: "bob-cmd-sheet-input-wrap" });
    inputWrap.createEl("span", { cls: "bob-cmd-sheet-prompt", text: "❯" });
    this.inputEl = inputWrap.createEl("input", { cls: "bob-cmd-sheet-input", attr: { type: "text" } });
    try {
      this.inputEl.value = this.query;
      this.inputEl.setAttribute("placeholder", "Type a command…");
    } catch (error) {
      // Headless stubs may not store attributes.
    }
    this.inputEl.addEventListener("input", () => {
      this.query = String(this.inputEl.value || "");
      this.hint = null;
      if (this.stage !== "list") {
        this.stage = "list";
        this.previewRunId = null;
        this.previewResult = null;
      }
      this.rebuildRows();
      this.render();
      this.refocusInput();
    });
  }

  refocusInput() {
    try {
      if (this.stage === "list" && this.inputEl && typeof this.inputEl.focus === "function") this.inputEl.focus();
    } catch (error) {
      // Focus is best effort.
    }
  }

  renderList() {
    const list = this.contentEl.createEl("div", { cls: "bob-cmd-sheet-list" });
    this.rowEls = new Map();
    const query = this.query.trim();
    if (!this.visible.length) {
      const empty = list.createEl("div", { cls: "bob-cmd-sheet-empty" });
      empty.setText(query ? "No matching command" : "No commands yet — is bob on PATH?");
      return;
    }
    if (!query) {
      for (const group of this.groups) {
        list.createEl("div", { cls: "bob-cmd-sheet-section", text: group.title });
        for (const row of group.rows) this.renderRow(list, row);
      }
      return;
    }
    for (const row of this.visible) this.renderRow(list, row);
  }

  renderRow(list, row) {
    const selected = row.key === this.selectedKey;
    const cls = "bob-cmd-row" + (selected ? " is-selected" : "") + (row.unavailable ? " is-unavailable" : "");
    const el = list.createEl("div", { cls });
    const icon = el.createEl("span", { cls: "bob-cmd-row-icon" });
    cmSheetSetIcon(icon, (CM_SHEET_ICONS[row.icon] || CM_SHEET_ICONS[row.subkind]) || "command", CM_SHEET_ICON_FALLBACK[row.icon] || CM_SHEET_ICON_FALLBACK[row.subkind] || "·");
    const path = Array.isArray(row.path) ? row.path.join(" ") : String(row.path || "");
    el.createEl("span", { cls: "bob-cmd-row-path", text: path });
    el.createEl("span", { cls: "bob-cmd-row-title", text: row.tagline ? row.title + " — " + row.tagline : row.title });
    const chips = el.createEl("span", { cls: "bob-cmd-row-chips" });
    if (row.effect && row.effect !== "opens") chips.createEl("span", { cls: "bob-cmd-chip-" + row.effect, text: row.effect });
    if (row.effect === "opens") chips.createEl("span", { cls: "bob-cmd-chip-opens", text: "opens" });
    if (row.hasPreview) chips.createEl("kbd", { cls: "bob-cmd-kbd", text: "⇧↵" });
    const duration = cmSheetMedianDuration(this.runRecords, row, this.host);
    if (duration !== null) chips.createEl("span", { cls: "bob-cmd-row-duration", text: cmFormatDuration(duration) });
    if (row.kind === "recent") {
      chips.createEl("span", { cls: "bob-cmd-row-glyph", text: row.glyph || "?" });
      if (row.age) chips.createEl("span", { cls: "bob-cmd-row-age", text: row.age });
    }
    if (row.unavailable) chips.createEl("span", { cls: "bob-cmd-row-unavailable", text: row.unavailable });
    if (selected && (row.about || row.tagline)) {
      list.createEl("div", { cls: "bob-cmd-row-about", text: row.tagline || row.about });
    }
    el.addEventListener("click", () => {
      this.selectedKey = row.key;
      void this.activateRow(row, {});
    });
    this.rowEls.set(row.key, el);
    return el;
  }

  renderFooter() {
    const footer = this.contentEl.createEl("div", { cls: "bob-cmd-sheet-footer" });
    if (this.hint) {
      footer.createEl("span", { cls: "bob-cmd-sheet-hint is-warning", text: this.hint });
      return;
    }
    if (this.stage === "output" && this.previewRunId && !this.previewResult) {
      footer.createEl("span", { cls: "bob-cmd-sheet-hint", text: "preview running… ⌃↵ applies when it finishes" });
      return;
    }
    footer.createEl("span", { cls: "bob-cmd-sheet-hint", text: cmSheetFooterHints(this.stage) });
  }

  renderConfirm() {
    const row = this.confirmRow;
    const card = this.contentEl.createEl("div", { cls: "bob-cmd-confirm" });
    card.createEl("div", { cls: "bob-cmd-confirm-title", text: (row && row.title) || "Confirm" });
    card.createEl("div", {
      cls: "bob-cmd-confirm-text",
      text: (row && row.confirm) || "This command needs confirmation.",
    });
    card.createEl("div", { cls: "bob-cmd-confirm-argv", text: "bob " + cmSheetRowArgv(row).map(cmQuoteArg).join(" ") });
    const actions = card.createEl("div", { cls: "bob-cmd-confirm-actions" });
    const run = actions.createEl("button", { cls: "bob-cmd-confirm-run", text: "Run ⌃↵" });
    run.addEventListener("click", () => void this.confirmRun());
    const back = actions.createEl("button", { cls: "bob-cmd-confirm-back", text: "Back" });
    back.addEventListener("click", () => {
      this.stage = "list";
      this.confirmRow = null;
      this.render();
      this.refocusInput();
    });
  }

  handleSheetKeydown(event) {
    if (this.stage === "output") return this.handleOutputKeydown(event);
    if (this.stage === "confirm") {
      if (event && event.key === "Escape") {
        event.preventDefault();
        this.stage = "list";
        this.confirmRow = null;
        this.render();
        this.refocusInput();
        return true;
      }
      if (event && event.key === "Enter" && event.ctrlKey && !event.shiftKey) {
        event.preventDefault();
        void this.confirmRun();
        return true;
      }
      if (event && event.key === "Enter" && !event.ctrlKey && !event.metaKey) {
        event.preventDefault();
        return true;
      }
      return false;
    }
    const action = cmSheetListAction(event, { query: this.query });
    if (!action || action.type === "none") return false;
    if (typeof event.preventDefault === "function") event.preventDefault();
    if (typeof event.stopPropagation === "function") event.stopPropagation();
    if (action.type === "close") {
      this.close();
      return true;
    }
    if (action.type === "down") {
      this.select(1);
      return true;
    }
    if (action.type === "up") {
      this.select(-1);
      return true;
    }
    if (action.type === "help") {
      this.showHelp();
      return true;
    }
    if (action.type === "args") {
      const row = this.selectedRow();
      if (row && typeof this.onPickVim === "function") {
        // Placeholder for the args-vim phase; until then, Tab names the need.
        this.hint = "Argument mode lands with the args-vim phase";
        this.render();
        this.refocusInput();
      } else if (row) {
        this.hint = row.required && row.required.length
          ? "Missing " + row.required.map((arg) => arg.name || arg.slot).join(", ")
          : "Nothing to fill in — press ↵ to run";
        this.render();
        this.refocusInput();
      }
      return true;
    }
    const row = this.selectedRow();
    if (!row) return true;
    if (action.type === "run") void this.activateRow(row, {});
    else if (action.type === "preview") void this.activateRow(row, { preview: true });
    else if (action.type === "run-now") void this.activateRow(row, { force: true });
    return true;
  }

  async activateRow(row, opts = {}) {
    if (!row || row.unavailable) return { ok: false, reason: row && row.unavailable ? row.unavailable : "no row" };
    if (row.kind === "surface") return this.runSurface(row);
    if (row.kind === "plain") return this.runPlain(row);
    if (row.kind === "recent") return this.rerunRecent(row);
    const missing = cmSheetMissingPositional(row);
    if (missing) {
      this.hint = "Needs " + missing;
      this.render();
      this.refocusInput();
      return { ok: false, reason: "missing " + missing };
    }
    const argv = cmSheetRowArgv(row);
    if (opts.preview || (row.policy === "preview-first" && !opts.force)) {
      return this.runPreview(row, argv);
    }
    if (row.policy === "confirm" && !opts.force) {
      this.confirmRow = row;
      this.stage = "confirm";
      this.render();
      return { ok: true, stage: "confirm" };
    }
    if (row.presentation === "report") {
      return this.runReport(row, argv, { preview: false });
    }
    if (row.presentation === "inline") {
      this.close();
      return this.runner().run(argv, { entryId: row.entryId, title: row.title, trigger: "sheet" });
    }
    this.close();
    return this.runner().run(argv, {
      entryId: row.entryId, title: row.title, trigger: "sheet",
      ...(opts.force ? { skipGuards: true } : {}),
    });
  }

  async runSurface(row) {
    try {
      const commands = this.app && this.app.commands;
      if (!commands || typeof commands.executeCommandById !== "function") return { ok: false, reason: "no command runner" };
      this.close();
      await commands.executeCommandById(row.surfaceId);
      return { ok: true };
    } catch (error) {
      return { ok: false, reason: String((error && error.message) || error) };
    }
  }

  async runPlain(row) {
    if (row.action === "show-last-output" || row.action === "run-history") {
      const plugin = this.plugin;
      this.close();
      if (plugin && typeof plugin.commandModeOpenOutput === "function") {
        const runner = this.runner();
        const newest = runner && typeof runner.newestRecord === "function" ? runner.newestRecord() : null;
        if (!newest) return { ok: false, reason: "no command output yet" };
        return plugin.commandModeOpenOutput(newest.id);
      }
      return { ok: false, reason: "no output view yet" };
    }
    return this.runReport({ ...row, title: "bob help" }, ["--help"], { preview: false });
  }

  async rerunRecent(row) {
    const runner = this.runner();
    if (!runner) return { ok: false, reason: "no runner" };
    const argv = [...(row.argv || [])];
    if (row.presentation === "report") {
      return this.runReport(row, argv, { preview: false, entryId: row.entryId || undefined });
    }
    this.close();
    return runner.run(argv, {
      ...(row.entryId ? { entryId: row.entryId } : {}),
      title: row.title, trigger: "sheet-recent",
    });
  }

  async runPreview(row, argv) {
    if (!row.hasPreview) {
      if (row.presentation === "report") return this.runReport(row, argv, { preview: false });
      return this.activateRow(row, { force: false });
    }
    const runner = this.runner();
    if (!runner) return { ok: false, reason: "no runner" };
    this.previewRunId = null;
    this.previewResult = null;
    this.previewCarry = [];
    const settled = await runner.run(argv, {
      entryId: row.entryId, title: row.title, trigger: "sheet-preview", preview: true,
    });
    if (!settled || !settled.runId) {
      this.hint = (settled && settled.reason) || "Preview failed to start";
      this.render();
      this.refocusInput();
      return settled || { ok: false };
    }
    this.previewRunId = settled.runId;
    this.previewResult = settled;
    try {
      const record = cmPagerFindRecord(runner, settled.runId);
      if (record && Array.isArray(record.carry)) this.previewCarry = [...record.carry];
    } catch (error) {
      this.previewCarry = [];
    }
    this.enterOutput(settled.runId, row.title + " · preview", { previewOf: { row, argv } });
    return settled;
  }

  async runReport(row, argv, opts = {}) {
    const runner = this.runner();
    if (!runner) return { ok: false, reason: "no runner" };
    const settled = await runner.run(argv, {
      ...(opts.entryId !== undefined ? { entryId: opts.entryId } : (row.entryId ? { entryId: row.entryId } : {})),
      title: row.title || "Report", trigger: "sheet",
      ...(opts.preview ? { preview: true } : {}),
      ...(opts.skipGuards ? { skipGuards: true } : {}),
    });
    if (!settled || !settled.runId) {
      this.hint = (settled && settled.reason) || "Run failed to start";
      this.render();
      this.refocusInput();
      return settled || { ok: false };
    }
    this.enterOutput(settled.runId, row.title || "Report", {});
    return settled;
  }

  async confirmRun() {
    const row = this.confirmRow;
    if (!row) return { ok: false, reason: "nothing to confirm" };
    const argv = cmSheetRowArgv(row);
    this.confirmRow = null;
    if (row.presentation === "report") {
      this.stage = "list";
      // The card was the confirmation; the run itself skips the policy gate.
      return this.runReport(row, argv, { skipGuards: true });
    }
    this.close();
    return this.runner().run(argv, {
      entryId: row.entryId, title: row.title, trigger: "sheet", confirmed: true,
    });
  }

  showHelp() {
    const query = this.query.trim().replace(/\?$/, "").trim();
    const rows = query ? cmRankSheetRows(query, this.rows, this.frecency) : [];
    const selected = rows[0] || this.selectedRow();
    const argv = cmSheetHelpArgv(selected && selected.kind !== "recent" ? selected : null);
    const title = selected && selected.title ? selected.title + " · help" : "bob help";
    const runner = this.runner();
    if (!runner) return { ok: false, reason: "no runner" };
    return runner.run(argv, { title, trigger: "sheet-help" }).then((settled) => {
      if (!settled || !settled.runId) {
        this.hint = (settled && settled.reason) || "Help failed to start";
        this.render();
        this.refocusInput();
        return settled || { ok: false };
      }
      this.enterOutput(settled.runId, title, {});
      return settled;
    });
  }

  enterOutput(runId, title, opts = {}) {
    this.stage = "output";
    this.outputRunId = String(runId || "");
    this.outputTitle = String(title || "Output");
    this.outputStopConfirm = false;
    this.outputSearch = cmDefaultPagerSearch();
    this.previewOf = opts.previewOf || null;
    if (!this.previewOf) {
      this.previewRunId = null;
      this.previewResult = null;
      this.previewCarry = [];
    }
    this.render();
    this.startTail();
  }

  backToList() {
    this.stopTail();
    this.stage = "list";
    this.outputRunId = null;
    this.previewOf = null;
    this.render();
    this.refocusInput();
  }

  payload() {
    return cmPagerLoadPayload(this.runner(), this.outputRunId);
  }

  records() {
    const runner = this.runner();
    if (!runner) return [];
    try { return cmListRecords(runner.fs(), runner.runsDir()); }
    catch (error) { return []; }
  }

  startTail() {
    this.stopTail();
    this.tailTimer = setInterval(() => this.refreshOutput(), CM_TAIL_POLL_MS);
    if (this.tailTimer && typeof this.tailTimer.unref === "function") this.tailTimer.unref();
  }

  stopTail() {
    if (this.tailTimer) {
      try { clearInterval(this.tailTimer); } catch (error) { /* Best effort. */ }
      this.tailTimer = null;
    }
  }

  refreshOutput() {
    if (!this.sheetOpen || this.stage !== "output") return null;
    const runner = this.runner();
    const vaultBase = runner && typeof runner.deps.vaultBase === "function" ? runner.deps.vaultBase() : cmVaultBasePath(this.app);
    const payload = this.payload();
    if (!payload) return null;
    this.outputView = cmBuildPagerView(payload, {
      app: this.app,
      vaultBase,
      records: this.records(),
      search: this.outputSearch,
      wrap: this.outputWrap,
      stopConfirm: this.outputStopConfirm,
      queuedBehind: cmPagerQueuedBehind(runner),
      nowMs: Date.now(),
    });
    if (!this.outputBody) return this.outputView;
    this.outputNodes = cmRenderPagerView(this.outputBody, this.outputView, {
      onStop: () => this.requestOutputStop(),
      onOpenLog: () => this.openFullLog(),
      onLink: (link) => this.openOutputLink(link),
    });
    this.renderOutputFooter();
    return this.outputView;
  }

  renderOutput() {
    const wrap = this.contentEl.createEl("div", { cls: "bob-cmd-sheet-output" });
    const bar = wrap.createEl("div", { cls: "bob-cmd-sheet-output-bar" });
    bar.createEl("span", { cls: "bob-cmd-sheet-output-title", text: this.outputTitle });
    if (this.previewOf) {
      const apply = bar.createEl("button", {
        cls: "bob-cmd-sheet-apply" + (this.previewResult && !this.previewResult.ok ? " is-disabled" : ""),
        text: "Apply ⌃↵",
      });
      apply.addEventListener("click", () => void this.applyPreview());
    }
    this.outputBody = wrap.createEl("div", { cls: "bob-cmd-sheet-output-body" });
    const footerHost = wrap.createEl("div", { cls: "bob-cmd-sheet-footer" });
    this.outputFooterEl = footerHost;
    this.refreshOutput();
  }

  renderOutputFooter() {
    if (!this.outputFooterEl) return;
    this.outputFooterEl.empty();
    if (this.previewOf) {
      const failed = this.previewResult && !this.previewResult.ok;
      this.outputFooterEl.createEl("span", {
        cls: "bob-cmd-sheet-hint" + (failed ? " is-warning" : ""),
        text: failed ? "preview failed — apply disabled" : "⌃↵ apply · esc back to list · q close",
      });
      return;
    }
    this.outputFooterEl.createEl("span", { cls: "bob-cmd-sheet-hint", text: cmSheetFooterHints("output") });
  }

  async applyPreview() {
    const previewOf = this.previewOf;
    if (!previewOf) return { ok: false, reason: "no preview to apply" };
    if (this.previewResult && !this.previewResult.ok) return { ok: false, reason: "preview failed" };
    const { row, argv } = previewOf;
    const carry = this.previewCarry.length ? this.previewCarry : [];
    this.previewOf = null;
    this.previewRunId = null;
    this.previewResult = null;
    // The preview already ran, so Apply skips the preview-first gate. The
    // save-before-write guard still applies inside the runner.
    if (row.presentation === "report") {
      return this.runReport(row, [...argv, ...carry], { skipGuards: true });
    }
    this.close();
    return this.runner().run([...argv, ...carry], {
      entryId: row.entryId, title: row.title, trigger: "sheet-apply", skipGuards: true,
    });
  }

  requestOutputStop() {
    const record = this.outputView && this.outputView.record;
    if (!record || record.outcome !== "running") return { ok: false, reason: "run is not active" };
    if (record.effect !== "reads" && !this.outputStopConfirm) {
      this.outputStopConfirm = true;
      this.refreshOutput();
      return { ok: true, confirm: true };
    }
    this.outputStopConfirm = false;
    const runner = this.runner();
    if (!runner || typeof runner.stop !== "function") return { ok: false, reason: "run is not active" };
    const result = runner.stop(this.outputRunId);
    this.refreshOutput();
    return result;
  }

  openFullLog() {
    const runner = this.runner();
    if (!runner || typeof this.plugin.commandModeOpenPath !== "function") return { ok: false };
    const paths = cmRunFilePaths(runner.runsDir(), this.outputRunId, runner.pathModule());
    return this.plugin.commandModeOpenPath(paths.out);
  }

  openOutputLink(link) {
    const workspace = this.app && this.app.workspace;
    if (!workspace || typeof workspace.openLinkText !== "function") return { ok: false, reason: "note opener unavailable" };
    try {
      const opened = workspace.openLinkText(link.href || link.path, "", Boolean(link.newLeaf), {});
      return opened && typeof opened.then === "function" ? opened.then(() => ({ ok: true })) : { ok: true };
    } catch (error) {
      return { ok: false, reason: String((error && error.message) || error) };
    }
  }

  handleOutputKeydown(event) {
    if (!event || typeof event.key !== "string") return false;
    if (event.key === "Escape") {
      event.preventDefault();
      this.backToList();
      return true;
    }
    if (event.key === "q" && !event.ctrlKey && !event.metaKey) {
      const tag = event.target && event.target.tagName;
      if (tag !== "INPUT" && tag !== "TEXTAREA") {
        event.preventDefault();
        this.close();
        return true;
      }
    }
    if (event.key === ":" && !event.ctrlKey && !event.metaKey) {
      const tag = event.target && event.target.tagName;
      if (tag !== "INPUT" && tag !== "TEXTAREA") {
        event.preventDefault();
        this.backToList();
        return true;
      }
    }
    if (event.key === "Enter" && event.ctrlKey && !event.shiftKey && this.previewOf) {
      event.preventDefault();
      void this.applyPreview();
      return true;
    }
    const action = cmHandlePagerKey(event, {
      search: this.outputSearch,
      stopConfirm: this.outputStopConfirm,
      hasSelection: cmPagerHasSelection(),
    });
    if (!action || action.type === "none") return false;
    if (typeof event.preventDefault === "function") event.preventDefault();
    if (typeof event.stopPropagation === "function") event.stopPropagation();
    this.applyOutputAction(action);
    return true;
  }

  applyOutputAction(action) {
    if (!action) return;
    switch (action.type) {
      case "rerun":
        this.rerunOutput();
        break;
      case "copy-output":
        try {
          if (this.outputView) {
            const text = cmPagerCopyOutput(this.outputView);
            void cmPagerWriteClipboard(text);
          }
        } catch (error) { /* Clipboard is best effort. */ }
        break;
      case "copy-command":
        try {
          if (this.outputView) {
            const text = cmPagerCopyCommand(this.outputView);
            void cmPagerWriteClipboard(text);
          }
        } catch (error) { /* Clipboard is best effort. */ }
        break;
      case "history-older":
      case "history-newer": {
        const ids = cmPagerHistoryIds(this.records());
        const state = cmPagerHistoryState(ids, this.outputRunId, action.type === "history-older" ? -1 : 1);
        if (state && state.runId) {
          this.outputRunId = state.runId;
          this.outputStopConfirm = false;
          this.outputSearch = cmDefaultPagerSearch();
          this.refreshOutput();
        }
        break;
      }
      case "open-log":
        this.openFullLog();
        break;
      case "close":
        this.close();
        break;
      default:
        this.refreshOutput();
        break;
    }
  }

  rerunOutput() {
    const record = this.outputView && this.outputView.record;
    if (!record || !Array.isArray(record.argv)) return { ok: false, reason: "nothing to rerun" };
    const runner = this.runner();
    if (!runner) return { ok: false, reason: "no runner" };
    return runner.run([...record.argv], {
      ...(record.entry_id ? { entryId: record.entry_id } : {}),
      title: record.title, trigger: "sheet-rerun",
    }).then((settled) => {
      if (settled && settled.runId) {
        this.outputRunId = settled.runId;
        this.outputStopConfirm = false;
        this.outputSearch = cmDefaultPagerSearch();
        this.previewOf = null;
        this.refreshOutput();
      }
      return settled;
    });
  }
}
